paso(huevos_rancheros, 1, 'Lava el jitomate y el chile. Córtalos y licúa con cebolla, ajo, agua y sal.').
paso(huevos_rancheros, 2, 'Calienta una cucharada de aceite a fuego medio. Agrega la salsa y cocina 10 minutos, moviendo de vez en cuando.').
paso(huevos_rancheros, 3, 'Calienta las tortillas en un comal y reparte dos en cada plato.').
paso(huevos_rancheros, 4, 'En el aceite restante cocina los huevos a fuego medio-bajo hasta que clara y yema estén firmes.').
paso(huevos_rancheros, 5, 'Pon un huevo sobre cada tortilla y cubre con salsa caliente.').
paso(huevos_divorciados, 1, 'Hierve el jitomate en media taza de agua durante 8 minutos. Licúa con la mitad de la cebolla, del ajo y de la sal.').
paso(huevos_divorciados, 2, 'Cuece aparte los tomatillos y el chile con el resto del agua. Licúa con la cebolla, ajo y sal restantes.').
paso(huevos_divorciados, 3, 'Calienta cada salsa por separado durante 5 minutos; usa media cucharada de aceite para cada una.').
paso(huevos_divorciados, 4, 'Calienta las tortillas. Cocina los huevos en la cucharada de aceite restante hasta que clara y yema estén firmes.').
paso(huevos_divorciados, 5, 'Sirve dos huevos sobre dos tortillas por persona. Baña uno con salsa roja y otro con salsa verde.').
paso(omelette_espinacas, 1, 'Lava y desinfecta las espinacas. Escúrrelas y pícalas; desmorona el queso.').
paso(omelette_espinacas, 2, 'Bate los huevos con la sal y divide en dos partes iguales.').
paso(omelette_espinacas, 3, 'Calienta media cucharada de aceite en un sartén pequeño a fuego bajo. Saltea la mitad de las espinacas un minuto.').
paso(omelette_espinacas, 4, 'Vierte la mitad del huevo. Tapa y cocina hasta que la superficie esté firme; agrega la mitad del queso y dobla con una espátula.').
paso(omelette_espinacas, 5, 'Retira el omelette y repite con el resto del aceite, espinacas, huevo y queso.').
paso(molletes_frijol, 1, 'Precalienta el horno a 180 °C. Corta los bolillos a lo largo.').
paso(molletes_frijol, 2, 'Calienta el aceite, agrega los frijoles escurridos y la mitad de la sal. Machaca hasta formar una pasta.').
paso(molletes_frijol, 3, 'Unta los cuatro medios bolillos con frijoles y distribuye el queso.').
paso(molletes_frijol, 4, 'Hornea en una charola de 8 a 10 minutos, hasta que el queso se derrita.').
paso(molletes_frijol, 5, 'Pica el jitomate y la cebolla, mezcla con la sal restante y reparte sobre los molletes al servir.').
paso(chilaquiles_verdes, 1, 'Quita la cáscara de los tomatillos y lávalos junto con el chile.').
paso(chilaquiles_verdes, 2, 'Cuécelos con el agua durante 10 minutos y deja entibiar antes de licuar.').
paso(chilaquiles_verdes, 3, 'Licúa con la cebolla, el ajo y la sal. Calienta el aceite y cocina la salsa 5 minutos.').
paso(chilaquiles_verdes, 4, 'Agrega los totopos y mezcla durante uno o dos minutos para cubrirlos sin deshacerlos.').
paso(chilaquiles_verdes, 5, 'Sirve de inmediato y reparte el queso fresco encima.').
paso(chilaquiles_rojos, 1, 'Retira tallo y semillas del guajillo. Lava el chile y los jitomates.').
paso(chilaquiles_rojos, 2, 'Cuece ambos en el agua durante 10 minutos. Deja entibiar y licúa con cebolla, ajo y sal.').
paso(chilaquiles_rojos, 3, 'Calienta el aceite y cocina la salsa a fuego medio durante 5 minutos.').
paso(chilaquiles_rojos, 4, 'Incorpora los totopos y mezcla uno o dos minutos, según qué tan suaves los prefieras.').
paso(chilaquiles_rojos, 5, 'Divide en dos platos y reparte la crema por encima.').
paso(enfrijoladas_queso, 1, 'Licúa los frijoles con el agua, la cebolla, el ajo y la sal.').
paso(enfrijoladas_queso, 2, 'Calienta el aceite en una cacerola. Agrega la salsa de frijol y cocina 8 minutos a fuego bajo; mueve para que no se pegue.').
paso(enfrijoladas_queso, 3, 'Calienta las tortillas en un comal para que se puedan doblar.').
paso(enfrijoladas_queso, 4, 'Sumerge cada tortilla en la salsa, rellena con parte del queso y dobla.').
paso(enfrijoladas_queso, 5, 'Reparte tres por plato y termina con la salsa y el queso restantes.').
paso(entomatadas_queso, 1, 'Lava y corta los jitomates. Licúa con cebolla, ajo, agua y sal.').
paso(entomatadas_queso, 2, 'Calienta el aceite y cocina la salsa 12 minutos a fuego medio-bajo, moviendo ocasionalmente.').
paso(entomatadas_queso, 3, 'Calienta las tortillas en un comal hasta que estén flexibles.').
paso(entomatadas_queso, 4, 'Pasa las tortillas por la salsa, rellena con queso y dobla por la mitad.').
paso(entomatadas_queso, 5, 'Reparte en dos platos, baña con la salsa restante y sirve.').
paso(enchiladas_suizas, 1, 'Cuece el pollo en tres cuartos de litro de agua de 20 a 25 minutos, hasta que esté completamente cocido. Deshebra con dos tenedores.').
paso(enchiladas_suizas, 2, 'Cuece los tomatillos y el chile en el cuarto de litro de agua restante durante 10 minutos. Deja entibiar.').
paso(enchiladas_suizas, 3, 'Licúa los tomatillos, chile y su agua con cebolla, ajo, crema y sal. Cocina la salsa 5 minutos a fuego bajo.').
paso(enchiladas_suizas, 4, 'Precalienta el horno a 180 °C. Calienta las tortillas, rellena con pollo y acomoda en un refractario.').
paso(enchiladas_suizas, 5, 'Cubre con salsa y queso. Hornea de 10 a 15 minutos hasta que el queso se derrita y el centro esté caliente.').
paso(tostadas_tinga, 1, 'Cuece el pollo en tres cuartos de litro de agua de 20 a 25 minutos, hasta que esté bien cocido. Deshebra y reserva.').
paso(tostadas_tinga, 2, 'Rebana la cebolla. Licúa el jitomate, ajo, chipotle, sal y el cuarto de litro de agua restante.').
paso(tostadas_tinga, 3, 'Calienta el aceite y sofríe la cebolla a fuego medio durante 5 minutos.').
paso(tostadas_tinga, 4, 'Agrega la salsa y cocina 10 minutos. Incorpora el pollo y calienta 5 minutos más.').
paso(tostadas_tinga, 5, 'Reparte la tinga sobre las tostadas justo antes de servir.').
paso(picadillo_papas, 1, 'Pela las papas y córtalas en cubos pequeños. Pica la cebolla.').
paso(picadillo_papas, 2, 'Licúa el jitomate con el ajo, el agua y la sal.').
paso(picadillo_papas, 3, 'Calienta el aceite y sofríe la cebolla 3 minutos. Agrega la carne y sepárala con una cuchara mientras se cocina.').
paso(picadillo_papas, 4, 'Cuando la carne esté bien cocida, añade la papa y la salsa. Tapa y cocina a fuego bajo unos 20 minutos.').
paso(picadillo_papas, 5, 'Revisa que las papas estén suaves al pincharlas. Sirve caliente.').
paso(sopa_fideo, 1, 'Lava y corta los jitomates. Licúa con cebolla, ajo y una taza del agua medida.').
paso(sopa_fideo, 2, 'Calienta el aceite en una olla y dora el fideo a fuego medio durante 2 o 3 minutos, moviendo constantemente.').
paso(sopa_fideo, 3, 'Vierte la salsa con cuidado y cocina 5 minutos.').
paso(sopa_fideo, 4, 'Agrega el resto del agua y la sal. Al hervir, baja el fuego y cocina de 8 a 10 minutos, hasta que el fideo esté suave.').
paso(sopa_fideo, 5, 'Apaga y sirve; evita seguir hirviendo para que la pasta no se deshaga.').
paso(sopa_lentejas, 1, 'Revisa las lentejas, retira piedritas y enjuaga. Pica jitomate, zanahoria, cebolla y ajo.').
paso(sopa_lentejas, 2, 'Calienta el aceite y sofríe la cebolla y el ajo durante 2 minutos.').
paso(sopa_lentejas, 3, 'Agrega el jitomate y la zanahoria; cocina 5 minutos.').
paso(sopa_lentejas, 4, 'Añade las lentejas y el agua. Cuando hierva, tapa parcialmente y cocina a fuego bajo de 25 a 30 minutos.').
paso(sopa_lentejas, 5, 'Comprueba que las lentejas estén suaves, agrega la sal y sirve.').
paso(papas_mexicana, 1, 'Pela las papas y córtalas en cubos de un centímetro. Pica jitomate, cebolla y chile.').
paso(papas_mexicana, 2, 'Calienta el aceite y cocina la papa a fuego medio durante 8 minutos, moviendo.').
paso(papas_mexicana, 3, 'Añade cebolla y chile y cocina 3 minutos más.').
paso(papas_mexicana, 4, 'Incorpora jitomate, agua y sal. Tapa y cocina de 10 a 15 minutos a fuego bajo.').
paso(papas_mexicana, 5, 'Destapa y revisa que la papa esté suave. Cocina unos minutos más si queda demasiado líquido.').
paso(rajas_crema, 1, 'Asa los poblanos en un comal, volteándolos hasta que la piel se ampolle.').
paso(rajas_crema, 2, 'Ponlos en un recipiente tapado 10 minutos. Retira piel, tallos y semillas; corta en tiras.').
paso(rajas_crema, 3, 'Rebana la cebolla y sofríela con el aceite durante 5 minutos.').
paso(rajas_crema, 4, 'Agrega las rajas y el maíz cocido y cocina otros 5 minutos.').
paso(rajas_crema, 5, 'Añade crema y sal. Calienta a fuego bajo 3 minutos, sin hervir fuerte, y sirve.').
paso(sincronizadas_champinones, 1, 'Limpia y rebana los champiñones; pica la cebolla.').
paso(sincronizadas_champinones, 2, 'Calienta el aceite y sofríe la cebolla 2 minutos. Agrega champiñones y sal.').
paso(sincronizadas_champinones, 3, 'Cocina de 6 a 8 minutos, hasta que se evapore el líquido.').
paso(sincronizadas_champinones, 4, 'Distribuye el relleno y el queso sobre dos tortillas. Cubre cada una con otra tortilla.').
paso(sincronizadas_champinones, 5, 'Dora en un comal a fuego bajo por ambos lados hasta derretir el queso. Corta en cuartos.').
paso(tostadas_atun, 1, 'Escurre el atún y desmenúzalo en un recipiente.').
paso(tostadas_atun, 2, 'Lava las verduras. Corta el jitomate y el pepino en cubos y pica la cebolla.').
paso(tostadas_atun, 3, 'Mezcla el atún con las verduras, el limón y la sal.').
paso(tostadas_atun, 4, 'Abre el aguacate, retira hueso y cáscara y córtalo en rebanadas.').
paso(tostadas_atun, 5, 'Reparte la mezcla sobre las tostadas y termina con el aguacate. Sirve al momento.').
paso(tortitas_papa_queso, 1, 'Pela las papas, córtalas en cubos y cuécelas en el agua unos 20 minutos, hasta que estén suaves.').
paso(tortitas_papa_queso, 2, 'Escurre muy bien, machaca y deja entibiar para que el huevo no se cueza al mezclar.').
paso(tortitas_papa_queso, 3, 'Añade huevo, queso desmoronado, harina y sal. Mezcla y forma seis tortitas pequeñas.').
paso(tortitas_papa_queso, 4, 'Calienta el aceite a fuego medio y cocina las tortitas de 3 a 4 minutos por lado.').
paso(tortitas_papa_queso, 5, 'Retira cuando estén doradas y firmes por dentro. Deja escurrir en papel absorbente.').
paso(nopales_huevo, 1, 'Usa nopales limpios y sin espinas. Lava y corta en tiras cortas.').
paso(nopales_huevo, 2, 'Cuécelos en el agua de 10 a 15 minutos, hasta que estén suaves. Escurre y enjuaga.').
paso(nopales_huevo, 3, 'Pica la cebolla y sofríela en el aceite a fuego medio durante 3 minutos.').
paso(nopales_huevo, 4, 'Agrega los nopales escurridos y cocina 2 minutos.').
paso(nopales_huevo, 5, 'Bate los huevos con sal, vierte al sartén y remueve hasta que estén completamente cocidos.').
paso(sopa_tortilla, 1, 'Retira tallo y semillas del pasilla. Tuéstalo unos segundos sin quemarlo y remójalo 10 minutos en una taza del agua caliente medida.').
paso(sopa_tortilla, 2, 'Licúa el chile y su agua con jitomate, cebolla y ajo.').
paso(sopa_tortilla, 3, 'Calienta una cucharada de aceite y cocina la salsa 8 minutos. Añade el agua restante y la sal; hierve suavemente 10 minutos.').
paso(sopa_tortilla, 4, 'Corta las tortillas en tiras delgadas. Dóralas en el aceite restante, por tandas, y escurre en papel.').
paso(sopa_tortilla, 5, 'Sirve el caldo en dos tazones. Agrega las tiras de tortilla, el queso y el aguacate justo antes de comer.').
paso(pasta_ajo_aceite, 1, 'Hierve el agua con la sal y cuece la pasta según el tiempo del envase.').
paso(pasta_ajo_aceite, 2, 'Antes de escurrir, separa media taza del agua de cocción.').
paso(pasta_ajo_aceite, 3, 'Rebana el ajo y caliéntalo con el aceite a fuego bajo hasta que esté apenas dorado; evita quemarlo.').
paso(pasta_ajo_aceite, 4, 'Agrega la pasta escurrida y el agua reservada al sartén. Mezcla a fuego medio durante un minuto.').
paso(pasta_ajo_aceite, 5, 'Lava y pica el perejil, incorpora y sirve inmediatamente.').
paso(pasta_atun, 1, 'Cuece la pasta en el agua con la sal, siguiendo las instrucciones del envase. Reserva media taza de agua antes de escurrir.').
paso(pasta_atun, 2, 'Escurre el atún. Pica el ajo y el perejil lavado.').
paso(pasta_atun, 3, 'Calienta el aceite a fuego bajo y cocina el ajo un minuto, sin quemarlo.').
paso(pasta_atun, 4, 'Incorpora atún, pasta y agua reservada. Mezcla y calienta 2 minutos.').
paso(pasta_atun, 5, 'Apaga el fuego y añade el jugo de limón y el perejil. Sirve caliente.').
paso(pasta_pesto_almendra, 1, 'Lava y desinfecta la albahaca. Tuesta las almendras en un sartén seco durante 2 minutos, moviendo.').
paso(pasta_pesto_almendra, 2, 'Cuece la pasta con el agua y la sal según el envase. Reserva media taza de agua y escurre.').
paso(pasta_pesto_almendra, 3, 'Licúa albahaca, almendras, parmesano, ajo y aceite. Agrega poco a poco el agua reservada para obtener una salsa.').
paso(pasta_pesto_almendra, 4, 'Fuera del fuego, mezcla la pasta caliente con el pesto.').
paso(pasta_pesto_almendra, 5, 'Divide en dos platos y sirve de inmediato.').
paso(espagueti_poblano, 1, 'Asa los poblanos en un comal. Tápalos en un recipiente 10 minutos; retira piel, tallos y semillas.').
paso(espagueti_poblano, 2, 'Mientras reposan los chiles, cuece la pasta en el agua con la mitad de la sal. Escurre.').
paso(espagueti_poblano, 3, 'Licúa los poblanos con crema, leche, ajo y la sal restante.').
paso(espagueti_poblano, 4, 'Derrite la mantequilla a fuego bajo, añade la salsa y cocina 5 minutos sin hervir fuerte.').
paso(espagueti_poblano, 5, 'Incorpora la pasta y mezcla durante 2 minutos. Sirve caliente.').
paso(arroz_frito_huevo, 1, 'Usa arroz ya cocido, enfriado rápidamente y conservado en refrigeración. Corta la zanahoria en cubos pequeños y pica el cebollín.').
paso(arroz_frito_huevo, 2, 'Calienta la mitad del aceite. Bate los huevos y cocínalos removiendo hasta que estén firmes; retira a un plato.').
paso(arroz_frito_huevo, 3, 'Añade el aceite restante y saltea zanahoria y chícharos hasta que estén suaves.').
paso(arroz_frito_huevo, 4, 'Agrega el arroz y la soya. Mezcla a fuego medio-alto hasta que todo esté bien caliente.').
paso(arroz_frito_huevo, 5, 'Reincorpora el huevo y el cebollín. Mezcla un minuto y sirve.').
paso(fideos_arroz_pollo, 1, 'Prepara los fideos con el agua según el envase, sin cocerlos de más. Escurre.').
paso(fideos_arroz_pollo, 2, 'Corta el pollo en tiras pequeñas. Usa otra tabla limpia para cortar zanahoria y pimiento; pica el ajo.').
paso(fideos_arroz_pollo, 3, 'Calienta el aceite y cocina el pollo hasta que esté completamente cocido. Retira a un plato limpio.').
paso(fideos_arroz_pollo, 4, 'Saltea las verduras y el ajo hasta suavizar.').
paso(fideos_arroz_pollo, 5, 'Reincorpora pollo, fideos y soya. Mezcla de 2 a 3 minutos hasta calentar todo.').
paso(pollo_teriyaki_casero, 1, 'Corta el pollo en cubos pequeños. Pica el ajo y ralla el jengibre.').
paso(pollo_teriyaki_casero, 2, 'Mezcla la soya, miel, agua, ajo y jengibre en un tazón.').
paso(pollo_teriyaki_casero, 3, 'Calienta el aceite y cocina el pollo por todos lados hasta que esté completamente cocido.').
paso(pollo_teriyaki_casero, 4, 'Baja el fuego y agrega la salsa. Cocina de 5 a 7 minutos, moviendo para cubrir el pollo.').
paso(pollo_teriyaki_casero, 5, 'Cuando la salsa espese ligeramente, apaga y reparte en dos platos.').
paso(camarones_ajillo, 1, 'Usa camarones descongelados en refrigeración, pelados y sin vena. Seca con papel de cocina.').
paso(camarones_ajillo, 2, 'Rebana el ajo. Quita tallo y semillas al guajillo y corta en tiras.').
paso(camarones_ajillo, 3, 'Calienta el aceite a fuego bajo. Cocina el ajo y el guajillo un minuto, sin quemarlos.').
paso(camarones_ajillo, 4, 'Agrega los camarones y la sal. Cocina por ambos lados hasta que estén opacos y firmes, sin partes translúcidas.').
paso(camarones_ajillo, 5, 'Apaga el fuego, agrega el limón, mezcla y sirve inmediatamente.').
paso(pollo_salsa_cacahuate, 1, 'Mezcla la crema de cacahuate con soya, limón y agua hasta que no queden grumos.').
paso(pollo_salsa_cacahuate, 2, 'Corta el pollo en tiras. Lava y corta el brócoli; pica el ajo en una tabla limpia.').
paso(pollo_salsa_cacahuate, 3, 'Calienta el aceite y cocina el pollo hasta que esté completamente cocido. Retira a un plato limpio.').
paso(pollo_salsa_cacahuate, 4, 'Saltea el ajo y el brócoli de 5 a 7 minutos, hasta que el brócoli esté tierno.').
paso(pollo_salsa_cacahuate, 5, 'Regresa el pollo, agrega la salsa y cocina a fuego bajo de 3 a 5 minutos, moviendo hasta que esté caliente.').
paso(ensalada_espinaca_almendra, 1, 'Lava y desinfecta espinacas y fresas. Escurre bien y retira los tallos de las fresas.').
paso(ensalada_espinaca_almendra, 2, 'Corta las fresas y el pepino en rebanadas.').
paso(ensalada_espinaca_almendra, 3, 'Tuesta las almendras en un sartén seco a fuego bajo durante 2 minutos, moviendo. Deja enfriar.').
paso(ensalada_espinaca_almendra, 4, 'Mezcla el aceite, limón y sal en un recipiente pequeño.').
paso(ensalada_espinaca_almendra, 5, 'Reparte espinacas, fresas, pepino y almendras en dos platos. Agrega el aderezo justo antes de comer.').
paso(huevos_mexicana, 1, 'Pica el tomate y la cebolla.').
paso(huevos_mexicana, 2, 'Calienta el aceite y sofríe la cebolla y el tomate durante 5 minutos.').
paso(huevos_mexicana, 3, 'Bate los huevos con la sal, incorpora al sartén y remueve hasta que estén completamente cocidos.').
paso(tacos_garbanzos, 1, 'Pica la cebolla y escurre los garbanzos cocidos.').
paso(tacos_garbanzos, 2, 'Sofríe la cebolla en el aceite y agrega los garbanzos, el comino y la sal. Cocina 8 minutos y aplasta ligeramente.').
paso(tacos_garbanzos, 3, 'Calienta las tortillas, distribuye el relleno y sirve.').
paso(pasta_tomate, 1, 'Cuece la pasta según las instrucciones del envase y reserva un poco de agua de cocción.').
paso(pasta_tomate, 2, 'Pica el tomate y el ajo. Calienta el aceite y sofríe el ajo brevemente.').
paso(pasta_tomate, 3, 'Agrega tomate, orégano y sal; cocina 12 minutos. Mezcla con la pasta y añade agua de cocción si hace falta.').
paso(ensalada_garbanzos, 1, 'Lava las verduras, corta el pepino y el tomate y pica la cebolla.').
paso(ensalada_garbanzos, 2, 'Escurre los garbanzos cocidos y mezcla con las verduras.').
paso(ensalada_garbanzos, 3, 'Añade el jugo de limón, el aceite y la sal. Mezcla y sirve.').
paso(calabacitas_maiz, 1, 'Lava y corta las calabacitas y los tomates. Pica la cebolla.').
paso(calabacitas_maiz, 2, 'Calienta el aceite y sofríe la cebolla y el tomate durante 5 minutos.').
paso(calabacitas_maiz, 3, 'Añade las calabacitas y el maíz cocido, sazona y cocina tapado de 10 a 15 minutos hasta suavizar.').
paso(arroz_verduras, 1, 'Corta la zanahoria y el pimiento en cubos pequeños.').
paso(arroz_verduras, 2, 'Calienta el aceite y saltea las verduras y los chícharos hasta que estén tiernos.').
paso(arroz_verduras, 3, 'Incorpora el arroz previamente cocido y refrigerado y la sal. Remueve hasta que todo esté bien caliente.').
paso(quesadillas_pollo, 1, 'Corta el pollo en tiras pequeñas.').
paso(quesadillas_pollo, 2, 'Calienta el aceite, añade el pollo y la sal y cocina hasta que el pollo esté completamente cocido.').
paso(quesadillas_pollo, 3, 'Rellena las tortillas con pollo y queso. Dobla y calienta por ambos lados hasta derretir el queso.').
paso(pollo_brocoli, 1, 'Corta el pollo en trozos y las verduras en piezas pequeñas. Pica el ajo.').
paso(pollo_brocoli, 2, 'Calienta el aceite y cocina el pollo hasta que esté completamente cocido. Retira a un plato limpio.').
paso(pollo_brocoli, 3, 'Saltea el ajo y las verduras hasta suavizar. Reincorpora el pollo, agrega la sal y calienta todo junto.').
paso(tacos_res, 1, 'Corta la res en tiras delgadas y la cebolla en rebanadas.').
paso(tacos_res, 2, 'Sofríe la cebolla en el aceite, agrega la carne y la sal y cocina hasta que la carne esté bien cocida.').
paso(tacos_res, 3, 'Calienta las tortillas, reparte la carne y sirve.').
paso(pescado_tomate, 1, 'Pica el tomate, la cebolla y el ajo.').
paso(pescado_tomate, 2, 'Sofríe la cebolla y el ajo en el aceite. Agrega el tomate y la sal y cocina 10 minutos.').
paso(pescado_tomate, 3, 'Coloca el pescado en la salsa, tapa y cocina hasta que esté completamente cocido y se separe fácilmente con un tenedor.').
paso(tacos_pollo_caseros, 1, 'Pica finamente la cebolla y el ajo.').
paso(tacos_pollo_caseros, 2, 'Calienta el aceite en un sartén a fuego medio y sofríe la cebolla durante unos minutos. Agrega el ajo y cocina brevemente.').
paso(tacos_pollo_caseros, 3, 'Agrega el pollo deshebrado, la sal, la pimienta y, si deseas, el orégano y el comino. Mezcla bien y cocina durante unos 5 minutos.').
paso(tacos_pollo_caseros, 4, 'Calienta las tortillas en un comal o sartén hasta que estén suaves y calientes.').
paso(tacos_pollo_caseros, 5, 'Sirve el pollo sobre las tortillas y agrega al gusto cilantro, salsa verde y queso fresco.').
paso(tacos_pollo_caseros, 6, 'Si quieres preparar tacos dorados, coloca el relleno en las tortillas, dóblalas y fríelas hasta que estén doradas y crujientes.').
paso(carne_res_verduras, 1, 'Corta la carne de res en tiras delgadas. Corta la cebolla y el pimiento morrón en tiras y pica finamente el ajo.').
paso(carne_res_verduras, 2, 'Calienta el aceite en un sartén grande a fuego medio-alto. Agrega la cebolla y el pimiento morrón y cocina durante 3 a 4 minutos, moviendo ocasionalmente.').
paso(carne_res_verduras, 3, 'Agrega la carne de res al mismo sartén y cocina hasta que esté bien cocida y ligeramente dorada.').
paso(carne_res_verduras, 4, 'Agrega el ajo, la sal y la pimienta. Si deseas, incorpora la salsa de soya y el chile serrano. Cocina durante 1 a 2 minutos más.').
paso(carne_res_verduras, 5, 'Si deseas utilizar brócoli o zanahoria, agrégalos junto con las demás verduras y cocina hasta que estén suaves pero todavía firmes.').
paso(carne_res_verduras, 6, 'Sirve la carne caliente y, si deseas, agrega cilantro al gusto.').
paso(lomo_cerdo_mostaza, 1, 'Corta el lomo de cerdo en medallones o tiras de tamaño similar. Pica finamente la cebolla y el ajo.').
paso(lomo_cerdo_mostaza, 2, 'Calienta el aceite en un sartén a fuego medio-alto. Sella el cerdo por ambos lados hasta que esté ligeramente dorado y retíralo temporalmente del sartén.').
paso(lomo_cerdo_mostaza, 3, 'En el mismo sartén, sofríe la cebolla durante unos minutos. Agrega el ajo y cocina brevemente.').
paso(lomo_cerdo_mostaza, 4, 'Agrega la mostaza y la media crema. Mezcla a fuego bajo hasta obtener una salsa uniforme. Añade sal y pimienta al gusto.').
paso(lomo_cerdo_mostaza, 5, 'Regresa el cerdo al sartén y cocina a fuego bajo hasta que esté completamente cocido y la salsa haya tomado consistencia.').
paso(lomo_cerdo_mostaza, 6, 'Si deseas, agrega un poco de miel, limón, champiñones o perejil para variar el sabor.').
paso(ceviche_pescado, 1, 'Corta el pescado en cubos y cocínalo al vapor en una vaporera hasta que esté completamente opaco y se separe fácilmente; el agua de la vaporera no forma parte del platillo.').
paso(ceviche_pescado, 2, 'Enfría rápidamente el pescado en un recipiente limpio dentro de un baño de agua con hielo.').
paso(ceviche_pescado, 3, 'Lava las verduras y desinfecta el cilantro. Pica cebolla, tomate, pepino y cilantro.').
paso(ceviche_pescado, 4, 'Mezcla pescado cocido, verduras, jugo de limón, sal y pimienta. El limón aporta sabor y no sustituye la cocción.').
paso(ceviche_pescado, 5, 'Añade los ingredientes opcionales que permita tu perfil y sirve frío; conserva refrigerado hasta comer.').
paso(pasta_pollo_champinones, 1, 'Cocina la pasta siguiendo las indicaciones del paquete. Escúrrela y reserva una pequeña cantidad del agua de cocción.').
paso(pasta_pollo_champinones, 2, 'Corta el pollo en trozos pequeños y los champiñones en rebanadas. Pica finamente la cebolla y el ajo.').
paso(pasta_pollo_champinones, 3, 'Derrite la mantequilla en un sartén grande a fuego medio. Agrega el pollo y cocina hasta que esté completamente cocido. Añade la cebolla, el ajo y los champiñones y cocina hasta que estén suaves.').
paso(pasta_pollo_champinones, 4, 'Retira el pollo y los champiñones del sartén y resérvalos en un recipiente limpio.').
paso(pasta_pollo_champinones, 5, 'En el mismo sartén, agrega la media crema y la leche. Mezcla a fuego bajo y añade el queso parmesano, la sal y la pimienta hasta formar una salsa cremosa.').
paso(pasta_pollo_champinones, 6, 'Agrega la pasta a la salsa y mezcla. Si la salsa está demasiado espesa, añade un poco del agua de cocción reservada.').
paso(pasta_pollo_champinones, 7, 'Regresa el pollo y los champiñones al sartén. Mezcla cuidadosamente y, si deseas, agrega perejil, orégano o una pequeña cantidad de nuez moscada.').
paso(bowl_garbanzos_verduras, 1, 'Corta la zanahoria, el pimiento morrón, la calabacita y la cebolla en trozos pequeños. Pica finamente el ajo.').
paso(bowl_garbanzos_verduras, 2, 'Calienta el aceite de oliva en un sartén a fuego medio. Agrega la cebolla y el ajo y cocina durante unos minutos.').
paso(bowl_garbanzos_verduras, 3, 'Agrega la zanahoria, el pimiento morrón y la calabacita. Cocina hasta que las verduras estén suaves pero todavía firmes.').
paso(bowl_garbanzos_verduras, 4, 'Agrega los garbanzos cocidos, la sal y la pimienta. Si deseas, añade paprika y comino y mezcla durante unos minutos.').
paso(bowl_garbanzos_verduras, 5, 'Coloca el arroz blanco cocido en un tazón y agrega encima la mezcla de garbanzos y verduras.').
paso(bowl_garbanzos_verduras, 6, 'Si deseas, agrega aguacate, cilantro, limón o yogurt natural antes de servir.').
paso(quesadillas_champinones, 1, 'Limpia y corta los champiñones en rebanadas. Pica finamente la cebolla y el ajo.').
paso(quesadillas_champinones, 2, 'Calienta el aceite en un sartén a fuego medio. Agrega la cebolla y cocina durante unos minutos. Añade el ajo y los champiñones.').
paso(quesadillas_champinones, 3, 'Cocina los champiñones hasta que reduzcan su tamaño y pierdan la mayor parte de su humedad. Agrega sal y pimienta al gusto.').
paso(quesadillas_champinones, 4, 'Calienta una tortilla en un comal o sartén. Coloca una porción de queso Oaxaca y agrega los champiñones sobre una mitad.').
paso(quesadillas_champinones, 5, 'Dobla la tortilla y cocina por ambos lados hasta que el queso se derrita y la tortilla esté ligeramente dorada.').
paso(quesadillas_champinones, 6, 'Sirve las quesadillas calientes y acompaña con salsa, cilantro, aguacate o los ingredientes opcionales que prefieras.').
paso(salmon_limon_verduras, 1, 'Corta la zanahoria, el pimiento morrón y la calabacita en piezas de tamaño similar. Pica finamente el ajo.').
paso(salmon_limon_verduras, 2, 'Sazona los filetes de salmon con sal y pimienta.').
paso(salmon_limon_verduras, 3, 'Calienta el aceite de oliva en un sartén grande a fuego medio. Agrega la zanahoria, el pimiento morrón y la calabacita y cocina hasta que estén suaves pero todavía firmes.').
paso(salmon_limon_verduras, 4, 'Retira las verduras y resérvalas en un recipiente limpio.').
paso(salmon_limon_verduras, 5, 'En el mismo sartén, coloca los filetes de salmon y cocina por ambos lados hasta que estén completamente cocidos.').
paso(salmon_limon_verduras, 6, 'Agrega el ajo y el jugo de limón al sartén. Si deseas, incorpora la mantequilla y el perejil. Cocina durante unos minutos, bañando ligeramente el salmón con la mezcla.').
paso(salmon_limon_verduras, 7, 'Sirve el salmon acompañado de las verduras. Si deseas, agrega paprika, ajo en polvo o una pequeña cantidad de miel.').
paso(arroz_frito_cerdo, 1, 'Corta el cerdo y la zanahoria en trozos pequeños. Pica finamente la cebolla y el ajo.').
paso(arroz_frito_cerdo, 2, 'Calienta el aceite en un sartén grande o wok a fuego medio-alto. Agrega el cerdo y cocina hasta que esté completamente cocido y ligeramente dorado.').
paso(arroz_frito_cerdo, 3, 'Agrega la cebolla, la zanahoria y el ajo. Cocina durante unos minutos hasta que las verduras comiencen a suavizarse.').
paso(arroz_frito_cerdo, 4, 'Mueve los ingredientes hacia un lado del sartén. Agrega el huevo en el espacio libre y revuelve hasta que esté completamente cocido.').
paso(arroz_frito_cerdo, 5, 'Agrega el arroz blanco cocido y frío. Mezcla todos los ingredientes y cocina durante unos minutos, moviendo constantemente para evitar que se pegue.').
paso(arroz_frito_cerdo, 6, 'Agrega sal y pimienta. Si deseas, incorpora salsa de soya, chícharos, cebollín, jengibre fresco o aceite de sésamo.').
paso(ensalada_pollo, 1, 'Cocina la pechuga de pollo hasta que esté completamente cocida. Déjala reposar unos minutos y córtala en tiras o cubos.').
paso(ensalada_pollo, 2, 'Lava y corta la lechuga, el tomate, el pepino y la cebolla morada. Corta el aguacate justo antes de servir.').
paso(ensalada_pollo, 3, 'Coloca la lechuga en un recipiente grande y agrega el tomate, el pepino, la cebolla morada y el aguacate.').
paso(ensalada_pollo, 4, 'Agrega el pollo sobre las verduras y mezcla suavemente.').
paso(ensalada_pollo, 5, 'Prepara el aderezo mezclando el aceite de oliva, el jugo de limón, la sal y la pimienta. Si deseas, agrega mostaza y miel.').
paso(ensalada_pollo, 6, 'Agrega el aderezo justo antes de servir. Si deseas, incorpora maíz, crutones, queso panela o semillas de girasol.').
paso(pescado_veracruzana, 1, 'Pica jitomates, cebolla y ajo y rebana las aceitunas.').
paso(pescado_veracruzana, 2, 'Calienta el aceite y sofríe cebolla y ajo 4 minutos.').
paso(pescado_veracruzana, 3, 'Añade jitomate, agua y orégano y cocina 10 minutos; incorpora aceitunas y alcaparras.').
paso(pescado_veracruzana, 4, 'Coloca los filetes en la salsa y tapa. Cocina a fuego bajo hasta que el pescado esté opaco y se separe fácilmente.').
paso(pescado_veracruzana, 5, 'Reparte los filetes y baña con la salsa caliente; las conservas ya aportan sal.').
paso(pescado_empapelado, 1, 'Precalienta el horno a 190 °C y corta dos hojas grandes de papel para hornear.').
paso(pescado_empapelado, 2, 'Lava y corta las verduras en tiras muy delgadas.').
paso(pescado_empapelado, 3, 'Coloca verduras y un filete en cada papel; reparte limón, aceite y sal.').
paso(pescado_empapelado, 4, 'Cierra los paquetes doblando bien los bordes y hornea de 20 a 25 minutos.').
paso(pescado_empapelado, 5, 'Abre con cuidado del vapor y comprueba que el pescado esté opaco y se separe fácilmente antes de servir.').
paso(tacos_pescado_baja, 1, 'Lava y desinfecta la col y corta muy fina. Mezcla yogurt y limón.').
paso(tacos_pescado_baja, 2, 'Corta el pescado en tiras y seca. Bate harina, huevo, agua y sal hasta obtener una mezcla espesa.').
paso(tacos_pescado_baja, 3, 'Calienta el aceite a fuego medio. Pasa el pescado por la mezcla y cocina por tandas hasta dorar y cocer el centro completamente.').
paso(tacos_pescado_baja, 4, 'Escurre en papel y calienta las tortillas.').
paso(tacos_pescado_baja, 5, 'Sirve pescado, col y aderezo dentro de las tortillas.').
paso(ceviche_camaron_cocido, 1, 'Hierve el agua y añade camarones limpios; cocina hasta que estén firmes y opacos, sin partes translúcidas.').
paso(ceviche_camaron_cocido, 2, 'Escurre y enfría rápidamente en un recipiente limpio dentro de un baño de agua con hielo.').
paso(ceviche_camaron_cocido, 3, 'Lava verduras y desinfecta cilantro; pica todo fino.').
paso(ceviche_camaron_cocido, 4, 'Mezcla camarón frío, verduras, cilantro, limón y sal. El limón aporta sabor y no sustituye la cocción.').
paso(ceviche_camaron_cocido, 5, 'Sirve frío y mantén refrigerado hasta consumir.').
paso(coctel_camaron_casero, 1, 'Cuece los camarones limpios en el agua hirviendo hasta que estén firmes y opacos; escurre y enfría rápidamente.').
paso(coctel_camaron_casero, 2, 'Licúa dos jitomates con puré de tomate, limón y sal.').
paso(coctel_camaron_casero, 3, 'Pica el jitomate restante, pepino, cebolla y cilantro lavado y desinfectado.').
paso(coctel_camaron_casero, 4, 'Mezcla camarones fríos con la salsa y las verduras.').
paso(coctel_camaron_casero, 5, 'Reparte en vasos o tazones y agrega aguacate en cubos; conserva refrigerado hasta servir.').
paso(arroz_mariscos, 1, 'Usa camarón limpio, calamar limpio en anillos y carne de mejillón sin concha. Mantén refrigerados hasta usar.').
paso(arroz_mariscos, 2, 'Pica pimiento y ajo; licúa jitomate con el agua. Enjuaga y escurre el arroz.').
paso(arroz_mariscos, 3, 'Sofríe pimiento y ajo en el aceite; añade arroz y mueve 2 minutos.').
paso(arroz_mariscos, 4, 'Agrega líquido y sal; tapa y cocina a fuego bajo 15 minutos.').
paso(arroz_mariscos, 5, 'Distribuye los mariscos, tapa y cocina hasta que el arroz esté suave y todos los mariscos completamente cocidos; el camarón debe estar opaco.').
paso(calamar_tomate, 1, 'Usa calamar limpio, descongelado en refrigeración y cortado en anillos.').
paso(calamar_tomate, 2, 'Pica cebolla y ajo y licúa el jitomate con agua.').
paso(calamar_tomate, 3, 'Sofríe cebolla y ajo con aceite 4 minutos; agrega calamar y mezcla.').
paso(calamar_tomate, 4, 'Vierte jitomate y sal, tapa y cocina a fuego bajo de 35 a 40 minutos, hasta que el calamar esté suave y bien cocido.').
paso(calamar_tomate, 5, 'Agrega perejil lavado y picado y sirve caliente.').
paso(mejillones_ajo_tomate, 1, 'Usa carne de mejillón sin concha, descongelada en refrigeración; revisa si el envase indica que ya está cocida.').
paso(mejillones_ajo_tomate, 2, 'Pica jitomates, cebolla y ajo.').
paso(mejillones_ajo_tomate, 3, 'Sofríe cebolla y ajo con el aceite 3 minutos; añade jitomate, agua y sal y cocina 10 minutos.').
paso(mejillones_ajo_tomate, 4, 'Agrega mejillones y cocina según su envase, hasta que estén completamente cocidos y calientes.').
paso(mejillones_ajo_tomate, 5, 'Termina con perejil lavado y picado y sirve de inmediato.').
paso(salpicon_pescado, 1, 'Cuece el pescado en el agua a hervor suave hasta que esté opaco y se separe fácilmente.').
paso(salpicon_pescado, 2, 'Escurre y enfría rápidamente en un recipiente limpio; desmenuza retirando cualquier espina.').
paso(salpicon_pescado, 3, 'Lava las verduras, ralla zanahoria y pica jitomate y cebolla.').
paso(salpicon_pescado, 4, 'Mezcla pescado, verduras, limón, aceite y sal.').
paso(salpicon_pescado, 5, 'Sirve frío sobre tostadas y mantén refrigerado hasta el momento de comer.').
paso(camarones_coco_horno, 1, 'Precalienta el horno a 200 °C y engrasa una charola con la mitad del aceite.').
paso(camarones_coco_horno, 2, 'Seca camarones pelados y sin vena. Mezcla coco, pan molido y sal en un plato.').
paso(camarones_coco_horno, 3, 'Pasa camarones por harina, huevo batido y mezcla de coco.').
paso(camarones_coco_horno, 4, 'Acomoda separados en la charola y pincela con el aceite restante.').
paso(camarones_coco_horno, 5, 'Hornea de 12 a 15 minutos, volteando a la mitad, hasta que el camarón esté firme y opaco y la cubierta dorada.').
paso(onigiri_atun, 1, 'Enjuaga el arroz varias veces y escurre. Cuécelo con el agua según el envase; deja reposar tapado 10 minutos.').
paso(onigiri_atun, 2, 'Escurre muy bien el atún y corta el nori en tiras.').
paso(onigiri_atun, 3, 'Deja entibiar el arroz solo lo necesario para manipularlo sin quemarte. Humedece tus manos limpias y reparte la sal.').
paso(onigiri_atun, 4, 'Forma cuatro bolas de arroz colocando atún en el centro; presiona suavemente para cerrar.').
paso(onigiri_atun, 5, 'Envuelve con nori y consume enseguida; refrigera de inmediato lo que no vayas a comer.').
paso(yaki_onigiri, 1, 'Enjuaga y cuece el arroz con el agua según el envase; deja reposar tapado 10 minutos.').
paso(yaki_onigiri, 2, 'Cuando esté tibio y puedas tocarlo, forma cuatro triángulos con manos limpias humedecidas.').
paso(yaki_onigiri, 3, 'Calienta un sartén antiadherente con el aceite de sésamo.').
paso(yaki_onigiri, 4, 'Dora los triángulos por ambos lados, pincela con soya y vuelve a dorar brevemente para que no se quemen.').
paso(yaki_onigiri, 5, 'Espolvorea ajonjolí y sirve calientes.').
paso(oyakodon_casero, 1, 'Corta el pollo pequeño y rebana la cebolla.').
paso(oyakodon_casero, 2, 'Calienta agua, soya y azúcar en un sartén; añade cebolla y cocina 5 minutos.').
paso(oyakodon_casero, 3, 'Agrega pollo, tapa y cocina hasta que esté completamente cocido.').
paso(oyakodon_casero, 4, 'Vierte el huevo batido, tapa y cocina a fuego bajo hasta que esté firme.').
paso(oyakodon_casero, 5, 'Calienta muy bien el arroz cocido y refrigerado, reparte en tazones y cubre con el guiso y cebollín.').
paso(gyudon_res, 1, 'Corta la res muy delgada y rebana la cebolla.').
paso(gyudon_res, 2, 'Hierve suavemente agua, soya, azúcar y jengibre picado.').
paso(gyudon_res, 3, 'Añade cebolla y cocina 8 minutos.').
paso(gyudon_res, 4, 'Incorpora la res y cocina hasta que esté bien cocida, separando las tiras.').
paso(gyudon_res, 5, 'Calienta el arroz cocido y refrigerado y sirve con la carne, cebolla y un poco del líquido.').
paso(katsudon_cerdo, 1, 'Corta el lomo en dos filetes delgados y pasa por harina, un huevo batido y pan molido.').
paso(katsudon_cerdo, 2, 'Calienta el aceite y cocina los filetes por ambos lados hasta que estén completamente cocidos; corta en tiras.').
paso(katsudon_cerdo, 3, 'En un sartén limpio cocina cebolla rebanada con agua y soya durante 7 minutos.').
paso(katsudon_cerdo, 4, 'Añade el cerdo y los huevos restantes batidos; tapa y cocina hasta que el huevo esté firme.').
paso(katsudon_cerdo, 5, 'Sirve sobre arroz cocido y refrigerado recalentado hasta que salga vapor.').
paso(sopa_miso_tofu, 1, 'Hidrata el wakame con una taza del agua medida durante 5 minutos.').
paso(sopa_miso_tofu, 2, 'Corta el tofu en cubos y pica el cebollín lavado.').
paso(sopa_miso_tofu, 3, 'Calienta el agua restante, añade tofu y wakame con su agua y cocina 5 minutos.').
paso(sopa_miso_tofu, 4, 'Disuelve el miso en un poco del caldo caliente en una taza y regrésalo a la olla.').
paso(sopa_miso_tofu, 5, 'Calienta sin hervir fuerte y reparte el cebollín al servir.').
paso(tofu_teriyaki, 1, 'Escurre y seca el tofu; corta en cubos y cubre con la mitad de la maicena.').
paso(tofu_teriyaki, 2, 'Mezcla agua, soya, azúcar y maicena restante.').
paso(tofu_teriyaki, 3, 'Dora el tofu con el aceite por todos lados.').
paso(tofu_teriyaki, 4, 'Añade la salsa y cocina a fuego bajo hasta que espese, girando el tofu con cuidado.').
paso(tofu_teriyaki, 5, 'Sirve sobre arroz cocido y refrigerado bien recalentado y termina con ajonjolí.').
paso(okonomiyaki_casero, 1, 'Lava y desinfecta la col y corta muy fina; pica cebollín.').
paso(okonomiyaki_casero, 2, 'Mezcla harina, agua y huevos y añade col y cebollín.').
paso(okonomiyaki_casero, 3, 'Calienta la mitad del aceite y forma una tortita con la mitad de la mezcla; cocina tapada a fuego medio-bajo 5 minutos por lado hasta cocer el centro.').
paso(okonomiyaki_casero, 4, 'Repite con aceite y mezcla restantes.').
paso(okonomiyaki_casero, 5, 'Calienta puré de tomate, soya y azúcar durante 2 minutos y reparte sobre las tortitas.').
paso(udon_pollo, 1, 'Corta el pollo en tiras y los hongos limpios en rebanadas.').
paso(udon_pollo, 2, 'Lleva el agua a hervor suave con el jengibre y la soya.').
paso(udon_pollo, 3, 'Añade el pollo y cuece unos 15 minutos o hasta que esté completamente cocido.').
paso(udon_pollo, 4, 'Incorpora hongos y udon y cocina según el tiempo del envase de los fideos.').
paso(udon_pollo, 5, 'Reparte en tazones y termina con cebollín lavado y picado.').
paso(salmon_miso, 1, 'Precalienta el horno a 190 °C y engrasa un refractario con el aceite.').
paso(salmon_miso, 2, 'Mezcla miso, miel y agua hasta obtener una pasta.').
paso(salmon_miso, 3, 'Acomoda el salmón y cubre con la pasta; deja reposar 10 minutos en refrigeración.').
paso(salmon_miso, 4, 'Hornea de 15 a 20 minutos, hasta que el centro esté opaco y se separe fácilmente con un tenedor.').
paso(salmon_miso, 5, 'Lava y rebana el pepino y sirve junto al salmón.').
paso(chana_masala, 1, 'Pica jitomate, cebolla, ajo y jengibre.').
paso(chana_masala, 2, 'Sofríe cebolla, ajo y jengibre con el aceite 5 minutos.').
paso(chana_masala, 3, 'Agrega comino, cúrcuma y garam masala; mezcla unos segundos.').
paso(chana_masala, 4, 'Incorpora jitomate, garbanzos, agua y sal y cocina tapado a fuego bajo 15 minutos.').
paso(chana_masala, 5, 'Machaca algunos garbanzos para espesar, mezcla y sirve caliente.').
paso(dal_lenteja_roja, 1, 'Revisa y enjuaga las lentejas; pica jitomate, cebolla, ajo y jengibre.').
paso(dal_lenteja_roja, 2, 'Cuece lentejas con agua y cúrcuma a fuego bajo de 20 a 25 minutos hasta suavizar.').
paso(dal_lenteja_roja, 3, 'Aparte, sofríe cebolla, ajo, jengibre y comino en el aceite 5 minutos.').
paso(dal_lenteja_roja, 4, 'Añade jitomate y cocina 8 minutos; incorpora a las lentejas con la sal.').
paso(dal_lenteja_roja, 5, 'Mezcla y hierve suavemente 3 minutos antes de servir.').
paso(aloo_gobi, 1, 'Pela y corta las papas en cubos pequeños; divide la coliflor en ramitos.').
paso(aloo_gobi, 2, 'Sofríe la cebolla picada en el aceite 4 minutos y agrega comino, cúrcuma y garam masala.').
paso(aloo_gobi, 3, 'Añade papa, coliflor y jitomate picado y mezcla.').
paso(aloo_gobi, 4, 'Agrega agua y sal, tapa y cocina a fuego bajo 20 minutos, moviendo ocasionalmente.').
paso(aloo_gobi, 5, 'Comprueba que papa y coliflor estén tiernas y sirve.').
paso(palak_panela, 1, 'Lava y desinfecta la espinaca; cocina tapada con el agua 3 minutos y licúa al entibiar.').
paso(palak_panela, 2, 'Pica cebolla, ajo, jengibre y jitomate.').
paso(palak_panela, 3, 'Sofríe cebolla, ajo y jengibre en el aceite; añade jitomate y garam masala y cocina 7 minutos.').
paso(palak_panela, 4, 'Agrega espinaca, yogurt y sal y mezcla a fuego bajo.').
paso(palak_panela, 5, 'Incorpora panela en cubos y calienta 5 minutos sin hervir fuerte.').
paso(pollo_tikka_casero, 1, 'Mezcla pollo en cubos, yogurt y la mitad del garam masala y la sal. Marina 15 minutos en refrigeración.').
paso(pollo_tikka_casero, 2, 'Pica cebolla, ajo y jengibre; licúa los jitomates.').
paso(pollo_tikka_casero, 3, 'Cocina el pollo con la mitad del aceite hasta que esté completamente cocido y reserva.').
paso(pollo_tikka_casero, 4, 'Sofríe cebolla, ajo y jengibre con el aceite restante; añade jitomate, paprika y especias y sal restantes y cocina 12 minutos.').
paso(pollo_tikka_casero, 5, 'Regresa el pollo, agrega crema y calienta 5 minutos a fuego bajo.').
paso(curry_camaron_coco, 1, 'Usa camarones limpios y descongelados en refrigeración; seca.').
paso(curry_camaron_coco, 2, 'Pica cebolla, ajo y jengibre y licúa el jitomate.').
paso(curry_camaron_coco, 3, 'Sofríe cebolla, ajo y jengibre en aceite; añade cúrcuma y comino.').
paso(curry_camaron_coco, 4, 'Vierte jitomate, coco y sal y hierve suavemente 10 minutos.').
paso(curry_camaron_coco, 5, 'Agrega camarones y cocina hasta que estén firmes y opacos, sin partes translúcidas.').
paso(arroz_basmati_especias, 1, 'Enjuaga el arroz hasta que el agua salga menos turbia; escurre.').
paso(arroz_basmati_especias, 2, 'Pica cebolla y sofríe en el aceite 3 minutos con comino y canela.').
paso(arroz_basmati_especias, 3, 'Añade arroz, agua, chícharos y sal.').
paso(arroz_basmati_especias, 4, 'Al hervir, tapa y cocina al mínimo unos 15 minutos o lo indicado por el envase.').
paso(arroz_basmati_especias, 5, 'Apaga y reposa tapado 10 minutos; separa los granos con un tenedor.').
paso(raita_pepino, 1, 'Lava el pepino y rállalo.').
paso(raita_pepino, 2, 'Exprime suavemente para retirar el exceso de agua.').
paso(raita_pepino, 3, 'Lava y desinfecta el cilantro y pícalo.').
paso(raita_pepino, 4, 'Bate el yogurt con comino y sal hasta que esté uniforme.').
paso(raita_pepino, 5, 'Mezcla pepino y cilantro con yogurt y sirve frío como acompañamiento.').
paso(aloo_matar, 1, 'Pela y corta las papas en cubos. Pica cebolla, ajo y jengibre y licúa jitomates.').
paso(aloo_matar, 2, 'Sofríe cebolla, ajo y jengibre en el aceite 5 minutos.').
paso(aloo_matar, 3, 'Añade jitomate y garam masala y cocina 7 minutos.').
paso(aloo_matar, 4, 'Incorpora papa, chícharos, agua y sal y cocina tapado a fuego bajo 20 minutos.').
paso(aloo_matar, 5, 'Revisa que la papa esté suave antes de repartir.').
paso(korma_verduras_nuez, 1, 'Remoja las nueces en media taza del agua caliente durante 10 minutos y licúa con esa agua y el yogurt.').
paso(korma_verduras_nuez, 2, 'Lava y corta las verduras en piezas pequeñas.').
paso(korma_verduras_nuez, 3, 'Sofríe cebolla picada con aceite, garam masala y cúrcuma 5 minutos.').
paso(korma_verduras_nuez, 4, 'Agrega verduras, agua restante y sal y cocina tapado hasta que estén tiernas.').
paso(korma_verduras_nuez, 5, 'Incorpora la salsa de nuez y yogurt y calienta 5 minutos a fuego bajo, sin hervir fuerte.').
paso(arroz_frito_camaron, 1, 'Usa arroz cocido y refrigerado. Seca los camarones limpios; pica zanahoria y cebollín.').
paso(arroz_frito_camaron, 2, 'Calienta la mitad del aceite y cocina los camarones hasta que estén opacos; reserva.').
paso(arroz_frito_camaron, 3, 'Agrega el aceite restante, zanahoria y chícharos; cocina hasta suavizar. Aparta a un lado y cocina el huevo batido hasta que esté firme.').
paso(arroz_frito_camaron, 4, 'Añade arroz y soya y saltea hasta que todo esté muy caliente.').
paso(arroz_frito_camaron, 5, 'Regresa los camarones y añade cebollín; mezcla un minuto y sirve.').
paso(arroz_pina_nuez_india, 1, 'Corta piña y pimiento en cubos. Usa arroz previamente cocido y refrigerado.').
paso(arroz_pina_nuez_india, 2, 'Tuesta las nueces en un sartén seco y retira.').
paso(arroz_pina_nuez_india, 3, 'Calienta el aceite, saltea pimiento y piña 4 minutos y aparta hacia un lado.').
paso(arroz_pina_nuez_india, 4, 'Añade el huevo batido y cocina completamente; incorpora arroz y soya y calienta bien.').
paso(arroz_pina_nuez_india, 5, 'Mezcla con nueces y cebollín lavado y picado antes de servir.').
paso(chow_mein_verduras, 1, 'Cuece los fideos con el agua según el envase y escurre.').
paso(chow_mein_verduras, 2, 'Lava las verduras y corta en tiras finas; pica el ajo.').
paso(chow_mein_verduras, 3, 'Calienta el aceite vegetal y saltea verduras y ajo hasta suavizar, sin deshacerlas.').
paso(chow_mein_verduras, 4, 'Añade los fideos y la soya y mezcla a fuego medio-alto 2 minutos.').
paso(chow_mein_verduras, 5, 'Apaga y agrega el aceite de sésamo; sirve caliente.').
paso(chow_mein_res, 1, 'Cuece los fideos según el envase con el agua y escurre.').
paso(chow_mein_res, 2, 'Corta la res en tiras; corta brócoli y cebolla usando una tabla limpia.').
paso(chow_mein_res, 3, 'Calienta el aceite y cocina la res por tandas hasta que esté bien cocida; reserva.').
paso(chow_mein_res, 4, 'Saltea brócoli, cebolla y jengibre hasta que las verduras estén tiernas.').
paso(chow_mein_res, 5, 'Regresa carne y fideos, añade soya y calienta todo junto 2 minutos.').
paso(pad_thai_camaron, 1, 'Prepara los fideos con el agua según el envase. Reserva un cuarto de taza de agua caliente y escurre.').
paso(pad_thai_camaron, 2, 'Disuelve tamarindo y azúcar en el agua reservada y añade salsa de pescado.').
paso(pad_thai_camaron, 3, 'Calienta el aceite y cocina los camarones limpios hasta que estén opacos; aparta a un lado y cocina el huevo batido.').
paso(pad_thai_camaron, 4, 'Agrega los fideos y la salsa; mezcla 2 minutos hasta calentar.').
paso(pad_thai_camaron, 5, 'Sirve con cacahuate tostado picado y cebollín lavado.').
paso(pad_thai_tofu, 1, 'Hidrata o cuece los fideos en el agua según el envase. Reserva un cuarto de taza de agua y escurre.').
paso(pad_thai_tofu, 2, 'Disuelve tamarindo y azúcar en el agua reservada y mezcla con soya.').
paso(pad_thai_tofu, 3, 'Escurre y seca el tofu; corta en cubos y dora con el aceite.').
paso(pad_thai_tofu, 4, 'Agrega zanahoria rallada y cocina 3 minutos; incorpora fideos y salsa.').
paso(pad_thai_tofu, 5, 'Calienta todo 2 minutos y termina con cacahuates tostados picados.').
paso(pollo_kung_pao, 1, 'Corta el pollo en cubos; corta pimiento y chile en una tabla limpia.').
paso(pollo_kung_pao, 2, 'Mezcla soya, vinagre, azúcar, maicena y agua.').
paso(pollo_kung_pao, 3, 'Calienta el aceite y cocina el pollo hasta que esté completamente cocido.').
paso(pollo_kung_pao, 4, 'Añade pimiento y chile y cocina 5 minutos; vierte la salsa y mezcla hasta espesar.').
paso(pollo_kung_pao, 5, 'Agrega cacahuates tostados y calienta un minuto antes de servir.').
paso(pollo_agridulce, 1, 'Corta el pollo en cubos y las verduras y piña en piezas parecidas.').
paso(pollo_agridulce, 2, 'Mezcla soya, puré de tomate, vinagre, azúcar, maicena y agua.').
paso(pollo_agridulce, 3, 'Calienta el aceite y cocina el pollo completamente.').
paso(pollo_agridulce, 4, 'Añade pimiento y piña y saltea 5 minutos.').
paso(pollo_agridulce, 5, 'Vierte la salsa y cocina moviendo de 3 a 5 minutos hasta que espese y esté caliente.').
paso(res_brocoli_soya, 1, 'Corta la carne en tiras delgadas y el brócoli en ramitos. Pica ajo y jengibre.').
paso(res_brocoli_soya, 2, 'Disuelve maicena en el agua y añade soya.').
paso(res_brocoli_soya, 3, 'Calienta el aceite y cocina la carne por tandas hasta que esté bien cocida; reserva.').
paso(res_brocoli_soya, 4, 'Saltea brócoli, ajo y jengibre 5 minutos; añade la salsa y cocina hasta espesar y suavizar el brócoli.').
paso(res_brocoli_soya, 5, 'Regresa la carne y mezcla 2 minutos para calentar.').
paso(tofu_agridulce, 1, 'Escurre el tofu, seca y corta en cubos. Corta piña y pimiento.').
paso(tofu_agridulce, 2, 'Mezcla puré de tomate, soya, vinagre, azúcar, maicena y agua.').
paso(tofu_agridulce, 3, 'Dora el tofu con el aceite y retira.').
paso(tofu_agridulce, 4, 'Saltea pimiento y piña 5 minutos y agrega la salsa, moviendo hasta que espese.').
paso(tofu_agridulce, 5, 'Regresa el tofu y calienta 2 minutos sin romperlo.').
paso(sopa_coco_pollo, 1, 'Corta el pollo en tiras pequeñas y rebana los hongos en una tabla limpia.').
paso(sopa_coco_pollo, 2, 'Hierve suavemente agua, leche de coco y jengibre 5 minutos.').
paso(sopa_coco_pollo, 3, 'Agrega el pollo y cocina 15 minutos o hasta que esté completamente cocido.').
paso(sopa_coco_pollo, 4, 'Añade hongos y salsa de pescado y cocina 5 minutos más.').
paso(sopa_coco_pollo, 5, 'Apaga y agrega limón y cilantro lavado. Sirve caliente; el jengibre sustituye a la galanga de otras versiones.').
paso(curry_rojo_vegetal, 1, 'Limpia los guajillos y remoja en el agua caliente 10 minutos. Licúa con ajo y jengibre.').
paso(curry_rojo_vegetal, 2, 'Lava y corta las verduras en piezas pequeñas.').
paso(curry_rojo_vegetal, 3, 'Calienta el aceite y cocina la salsa de chile 5 minutos.').
paso(curry_rojo_vegetal, 4, 'Añade verduras, leche de coco y sal y cocina tapado a fuego bajo 15 minutos.').
paso(curry_rojo_vegetal, 5, 'Comprueba que la coliflor esté tierna y sirve. Es una adaptación casera de curry rojo.').
paso(sopa_fideos_shiitake, 1, 'Limpia los shiitake frescos y rebana. Lava y desinfecta la espinaca.').
paso(sopa_fideos_shiitake, 2, 'Hierve el agua con ajo y jengibre picados 5 minutos.').
paso(sopa_fideos_shiitake, 3, 'Añade hongos y soya y cocina 8 minutos.').
paso(sopa_fideos_shiitake, 4, 'Agrega los fideos y cocina según el envase; incorpora la espinaca al final hasta suavizar.').
paso(sopa_fideos_shiitake, 5, 'Apaga y añade el aceite de sésamo. Sirve caliente.').
paso(pepino_sesamo, 1, 'Lava los pepinos y corta en medias lunas delgadas.').
paso(pepino_sesamo, 2, 'Tuesta el ajonjolí en un sartén seco sin quemarlo.').
paso(pepino_sesamo, 3, 'Mezcla soya, vinagre, aceite y azúcar hasta disolver.').
paso(pepino_sesamo, 4, 'Añade el pepino y mezcla para cubrirlo.').
paso(pepino_sesamo, 5, 'Deja reposar 5 minutos y termina con el ajonjolí.').
paso(rollitos_frescos_tofu, 1, 'Prepara los fideos con el agua según el envase; reserva el agua tibia en un recipiente amplio y escurre.').
paso(rollitos_frescos_tofu, 2, 'Escurre y seca el tofu, corta en tiras y dóralo con el aceite.').
paso(rollitos_frescos_tofu, 3, 'Lava y desinfecta la lechuga. Corta zanahoria y pepino en tiras finas.').
paso(rollitos_frescos_tofu, 4, 'Humedece un papel de arroz en el agua tibia, rellena con fideos, verduras y tofu y enrolla doblando los lados.').
paso(rollitos_frescos_tofu, 5, 'Repite con los papeles restantes y sirve con la soya aparte.').
paso(lechuga_pollo_asiatico, 1, 'Lava y desinfecta las hojas de lechuga y sécalas con cuidado.').
paso(lechuga_pollo_asiatico, 2, 'Pica el pollo muy fino. En una tabla limpia pica verduras, ajo y jengibre.').
paso(lechuga_pollo_asiatico, 3, 'Calienta el aceite y cocina el pollo hasta que esté completamente cocido, separándolo con una cuchara.').
paso(lechuga_pollo_asiatico, 4, 'Agrega verduras, ajo y jengibre y cocina 6 minutos; incorpora soya y calienta 2 minutos.').
paso(lechuga_pollo_asiatico, 5, 'Reparte el guiso en las hojas de lechuga y sirve.').
paso(pollo_almendrado, 1, 'Tuesta las almendras en un sartén seco y reserva.').
paso(pollo_almendrado, 2, 'Corta el pollo en tiras; corta pimiento y cebolla en una tabla limpia. Disuelve maicena en agua y soya.').
paso(pollo_almendrado, 3, 'Calienta el aceite y cocina completamente el pollo.').
paso(pollo_almendrado, 4, 'Añade pimiento y cebolla y cocina 5 minutos; vierte la salsa y mueve hasta que espese.').
paso(pollo_almendrado, 5, 'Incorpora las almendras y sirve caliente.').
paso(arroz_edamame_sesamo, 1, 'Cuece el edamame sin vaina con el agua según su envase y escurre.').
paso(arroz_edamame_sesamo, 2, 'Ralla la zanahoria y tuesta el ajonjolí en un sartén seco.').
paso(arroz_edamame_sesamo, 3, 'Calienta el aceite y saltea la zanahoria 3 minutos.').
paso(arroz_edamame_sesamo, 4, 'Añade arroz previamente cocido y refrigerado, edamame y soya. Calienta hasta que salga vapor por toda la mezcla.').
paso(arroz_edamame_sesamo, 5, 'Reparte y termina con ajonjolí.').
paso(bibimbap_vegetal, 1, 'Lava y desinfecta espinaca y pepino; corta verduras y hongos en tiras.').
paso(bibimbap_vegetal, 2, 'Saltea zanahoria, hongos y espinaca por separado usando parte del aceite vegetal.').
paso(bibimbap_vegetal, 3, 'Calienta el arroz cocido y refrigerado hasta que salga vapor y reparte en dos tazones.').
paso(bibimbap_vegetal, 4, 'Cocina los huevos con el aceite restante hasta que clara y yema estén firmes.').
paso(bibimbap_vegetal, 5, 'Acomoda verduras, pepino y huevo sobre el arroz y añade soya y aceite de sésamo.').
paso(bulgogi_res_casero, 1, 'Ralla la manzana sin corazón y mezcla con soya, ajo picado, azúcar y aceite de sésamo.').
paso(bulgogi_res_casero, 2, 'Corta la carne muy fina y marina en esa mezcla en refrigeración durante 20 minutos.').
paso(bulgogi_res_casero, 3, 'Rebana la cebolla y tuesta el ajonjolí en un sartén seco.').
paso(bulgogi_res_casero, 4, 'Calienta el aceite vegetal y cocina carne, marinada y cebolla por tandas hasta que la carne esté bien cocida.').
paso(bulgogi_res_casero, 5, 'Reparte y espolvorea el ajonjolí.').
paso(espagueti_bolonesa, 1, 'Pica cebolla y ajo; ralla zanahoria y licúa los jitomates.').
paso(espagueti_bolonesa, 2, 'Sofríe cebolla y ajo en el aceite; agrega carne y cocina completamente, desmenuzándola.').
paso(espagueti_bolonesa, 3, 'Añade zanahoria, jitomate, orégano y la mitad de la sal; cocina a fuego bajo 25 minutos.').
paso(espagueti_bolonesa, 4, 'Cuece la pasta en el agua con la sal restante según el envase y escurre.').
paso(espagueti_bolonesa, 5, 'Reparte la pasta y cubre con la salsa de carne caliente.').
paso(lasana_res, 1, 'Sofríe cebolla y ajo picados en el aceite; agrega carne y cocina completamente.').
paso(lasana_res, 2, 'Licúa jitomates y agrega a la carne con la mitad de la sal. Cocina la salsa 20 minutos.').
paso(lasana_res, 3, 'Prepara las láminas con el agua y la sal restante según el envase. Precalienta el horno a 180 °C.').
paso(lasana_res, 4, 'En un refractario pequeño alterna salsa, pasta y requesón; termina con salsa y mozzarella.').
paso(lasana_res, 5, 'Hornea 30 minutos hasta que burbujee y el centro esté caliente. Reposa 10 minutos antes de cortar.').
paso(carbonara_casera, 1, 'Cuece la pasta en el agua con sal; reserva media taza de agua antes de escurrir.').
paso(carbonara_casera, 2, 'Corta el tocino en tiras y cocínalo en un sartén hasta que esté bien cocido.').
paso(carbonara_casera, 3, 'Bate los huevos con parmesano rallado y pimienta.').
paso(carbonara_casera, 4, 'Añade la pasta y agua reservada al tocino y baja el fuego al mínimo.').
paso(carbonara_casera, 5, 'Incorpora el huevo moviendo constantemente hasta que esté cocido; la salsa puede quedar menos cremosa que la versión tradicional. Sirve.').
paso(fettuccine_alfredo, 1, 'Cuece la pasta en el agua con sal según el envase. Escurre.').
paso(fettuccine_alfredo, 2, 'Derrite la mantequilla a fuego bajo.').
paso(fettuccine_alfredo, 3, 'Añade crema y leche y calienta 3 minutos sin hervir fuerte.').
paso(fettuccine_alfredo, 4, 'Agrega parmesano rallado y pimienta; mezcla hasta integrar.').
paso(fettuccine_alfredo, 5, 'Incorpora la pasta, mezcla 2 minutos y sirve de inmediato.').
paso(pasta_arrabbiata, 1, 'Pica los jitomates y el ajo. Retira el tallo y las semillas del chile y trocéalo.').
paso(pasta_arrabbiata, 2, 'Calienta aceite, ajo y chile a fuego bajo un minuto, sin quemarlos.').
paso(pasta_arrabbiata, 3, 'Añade jitomate y la mitad de la sal; cocina 15 minutos.').
paso(pasta_arrabbiata, 4, 'Cuece la pasta con el agua y sal restante según el envase; escurre.').
paso(pasta_arrabbiata, 5, 'Mezcla pasta y salsa y termina con perejil lavado y picado.').
paso(pasta_puttanesca, 1, 'Pica jitomates, ajo y anchoas. Rebana las aceitunas.').
paso(pasta_puttanesca, 2, 'Cuece la pasta en el agua según el envase y escurre.').
paso(pasta_puttanesca, 3, 'Calienta el aceite y cocina ajo y anchoas un minuto, deshaciéndolas con una cuchara.').
paso(pasta_puttanesca, 4, 'Agrega jitomate, aceitunas y alcaparras; cocina 12 minutos a fuego medio-bajo.').
paso(pasta_puttanesca, 5, 'Incorpora la pasta y mezcla bien. Las anchoas y alcaparras ya aportan sal.').
paso(pasta_primavera, 1, 'Corta las verduras en piezas pequeñas y pica el ajo.').
paso(pasta_primavera, 2, 'Cuece la pasta con el agua y la mitad de la sal; agrega brócoli y chícharos los últimos 3 minutos. Escurre.').
paso(pasta_primavera, 3, 'Saltea ajo, zanahoria y calabacita en el aceite hasta suavizar.').
paso(pasta_primavera, 4, 'Mezcla la pasta y las verduras con la sal restante.').
paso(pasta_primavera, 5, 'Reparte parmesano rallado encima y sirve caliente.').
paso(pasta_brocoli_limon, 1, 'Lava el limón y ralla solo la parte verde o amarilla. Separa el brócoli en ramitos.').
paso(pasta_brocoli_limon, 2, 'Cuece la pasta con el agua y sal; añade el brócoli los últimos 4 minutos. Reserva media taza de agua y escurre.').
paso(pasta_brocoli_limon, 3, 'Calienta el aceite con el ajo picado durante un minuto.').
paso(pasta_brocoli_limon, 4, 'Incorpora pasta, brócoli, agua reservada y ralladura de limón; mezcla 2 minutos.').
paso(pasta_brocoli_limon, 5, 'Termina con parmesano y un poco del jugo del limón medido.').
paso(pasta_espinaca_requeson, 1, 'Lava y desinfecta las espinacas y pícalas.').
paso(pasta_espinaca_requeson, 2, 'Cuece la pasta con agua y sal; reserva media taza de agua y escurre.').
paso(pasta_espinaca_requeson, 3, 'Sofríe el ajo picado en el aceite un minuto y añade las espinacas hasta que bajen de volumen.').
paso(pasta_espinaca_requeson, 4, 'Mezcla requesón y agua reservada con las espinacas a fuego bajo.').
paso(pasta_espinaca_requeson, 5, 'Incorpora la pasta y calienta todo 2 minutos, moviendo.').
paso(pasta_camaron_ajo, 1, 'Usa camarones pelados, sin vena y descongelados en refrigeración. Seca bien.').
paso(pasta_camaron_ajo, 2, 'Cuece la pasta en agua con sal; reserva media taza de agua y escurre.').
paso(pasta_camaron_ajo, 3, 'Calienta el aceite con el ajo picado un minuto.').
paso(pasta_camaron_ajo, 4, 'Agrega camarones y cocina por ambos lados hasta que estén firmes y opacos, sin partes translúcidas.').
paso(pasta_camaron_ajo, 5, 'Añade pasta, agua reservada, limón y perejil lavado. Mezcla y sirve caliente.').
paso(pasta_salmon_cremosa, 1, 'Cuece la pasta con agua y la mitad de la sal y escurre.').
paso(pasta_salmon_cremosa, 2, 'Corta el salmón en cubos y sazona con la sal restante.').
paso(pasta_salmon_cremosa, 3, 'Calienta aceite y ajo picado; agrega el salmón y cocina hasta que esté opaco y se separe fácilmente.').
paso(pasta_salmon_cremosa, 4, 'Añade crema y limón y calienta a fuego bajo 3 minutos sin hervir fuerte.').
paso(pasta_salmon_cremosa, 5, 'Incorpora la pasta y mezcla suavemente para no deshacer el pescado.').
paso(ensalada_caprese, 1, 'Lava los jitomates y rebánalos.').
paso(ensalada_caprese, 2, 'Escurre y corta la mozzarella en rebanadas.').
paso(ensalada_caprese, 3, 'Lava y desinfecta la albahaca y seca las hojas.').
paso(ensalada_caprese, 4, 'Alterna jitomate, queso y hojas en dos platos.').
paso(ensalada_caprese, 5, 'Rocía aceite y reparte sal y pimienta justo antes de servir.').
paso(bruschetta_tomate, 1, 'Corta el pan en rebanadas diagonales.').
paso(bruschetta_tomate, 2, 'Pica jitomate y albahaca lavada y desinfectada; mezcla con una cucharada de aceite y sal.').
paso(bruschetta_tomate, 3, 'Tuesta el pan en un comal por ambos lados.').
paso(bruschetta_tomate, 4, 'Frota ligeramente el ajo cortado sobre el pan y unta con el aceite restante.').
paso(bruschetta_tomate, 5, 'Reparte el jitomate encima y sirve inmediatamente.').
paso(risotto_champinones, 1, 'Calienta el agua con sal y mantenla a hervor suave. Limpia y rebana los hongos; pica cebolla.').
paso(risotto_champinones, 2, 'Saltea hongos y cebolla en el aceite 7 minutos.').
paso(risotto_champinones, 3, 'Agrega el arroz y mezcla un minuto. Vierte un cucharón del agua caliente.').
paso(risotto_champinones, 4, 'Cocina removiendo y añade agua por cucharones conforme se absorba, durante unos 25 minutos, hasta que el arroz esté tierno.').
paso(risotto_champinones, 5, 'Apaga, mezcla mantequilla y parmesano y reposa 2 minutos antes de servir.').
paso(risotto_calabaza, 1, 'Pela la calabaza y corta en cubitos. Pica la cebolla y calienta el agua con sal.').
paso(risotto_calabaza, 2, 'Sofríe cebolla y calabaza en el aceite 7 minutos.').
paso(risotto_calabaza, 3, 'Agrega arroz y un cucharón de agua caliente; cocina moviendo.').
paso(risotto_calabaza, 4, 'Añade más agua conforme se absorba, durante 25 minutos o hasta que el arroz y la calabaza estén suaves.').
paso(risotto_calabaza, 5, 'Fuera del fuego, mezcla mantequilla y parmesano. Sirve cremoso.').
paso(noquis_tomate, 1, 'Pica los jitomates, ajo y albahaca lavada.').
paso(noquis_tomate, 2, 'Calienta el aceite y sofríe el ajo un minuto; añade jitomate y la mitad de la sal.').
paso(noquis_tomate, 3, 'Cocina la salsa 15 minutos a fuego bajo.').
paso(noquis_tomate, 4, 'Cuece los ñoquis en el agua con sal restante según su envase y retíralos con una espumadera.').
paso(noquis_tomate, 5, 'Mezcla con salsa y albahaca y reparte el parmesano encima.').
paso(polenta_champinones, 1, 'Calienta agua y leche con la mitad de la sal.').
paso(polenta_champinones, 2, 'Agrega la polenta en forma de lluvia y mezcla para evitar grumos.').
paso(polenta_champinones, 3, 'Cocina a fuego bajo según el envase, moviendo hasta que esté suave; incorpora parmesano.').
paso(polenta_champinones, 4, 'Aparte, saltea champiñones rebanados y ajo picado en aceite con la sal restante hasta dorar.').
paso(polenta_champinones, 5, 'Reparte la polenta caliente y coloca los hongos encima.').
paso(pizza_margarita_casera, 1, 'Precalienta el horno a la temperatura indicada por la base de pizza.').
paso(pizza_margarita_casera, 2, 'Licúa dos jitomates con orégano y sal; cocina la salsa 5 minutos.').
paso(pizza_margarita_casera, 3, 'Unta la base con salsa y distribuye mozzarella y el jitomate restante en rebanadas.').
paso(pizza_margarita_casera, 4, 'Hornea según el envase hasta que la base esté cocida y el queso derretido.').
paso(pizza_margarita_casera, 5, 'Agrega albahaca lavada y desinfectada y aceite de oliva. Corta y sirve.').
paso(berenjenas_parmesana, 1, 'Precalienta el horno a 200 °C. Rebana las berenjenas y unta con una cucharada de aceite.').
paso(berenjenas_parmesana, 2, 'Hornea las rebanadas en una charola 20 minutos, volteando a la mitad.').
paso(berenjenas_parmesana, 3, 'Licúa los jitomates y cocina con ajo picado, sal y aceite restante durante 12 minutos.').
paso(berenjenas_parmesana, 4, 'Alterna berenjena, salsa y mozzarella en un refractario; termina con parmesano.').
paso(berenjenas_parmesana, 5, 'Hornea 20 minutos hasta que esté caliente y gratinado. Reposa 5 minutos antes de servir.').
paso(minestrone_verduras, 1, 'Lava y corta todas las verduras en cubos pequeños.').
paso(minestrone_verduras, 2, 'Sofríe cebolla, apio y zanahoria en el aceite 5 minutos.').
paso(minestrone_verduras, 3, 'Agrega jitomate, calabacita, agua y sal y hierve suavemente 10 minutos.').
paso(minestrone_verduras, 4, 'Incorpora pasta y alubias y cocina el tiempo indicado para la pasta.').
paso(minestrone_verduras, 5, 'Revisa que verduras y pasta estén suaves y sirve caliente.').
paso(hummus_clasico, 1, 'Escurre los garbanzos y pela el ajo.').
paso(hummus_clasico, 2, 'Licúa garbanzos, tahini, limón, ajo, aceite y sal.').
paso(hummus_clasico, 3, 'Añade el agua poco a poco hasta lograr un puré suave.').
paso(hummus_clasico, 4, 'Lava y pela las zanahorias; lava el pepino y corta ambos en bastones.').
paso(hummus_clasico, 5, 'Reparte el hummus y sirve con los bastones de verdura.').
paso(falafel_horneado, 1, 'Precalienta el horno a 200 °C y engrasa una charola con una cucharada de aceite.').
paso(falafel_horneado, 2, 'Escurre y seca bien los garbanzos. Procesa con cebolla, ajo y perejil lavado, dejando textura gruesa.').
paso(falafel_horneado, 3, 'Mezcla con harina, comino y sal; refrigera 15 minutos para dar firmeza.').
paso(falafel_horneado, 4, 'Forma ocho tortitas pequeñas y acomoda en la charola; unta con el aceite restante.').
paso(falafel_horneado, 5, 'Hornea de 25 a 30 minutos, volteando a la mitad, hasta que estén firmes y doradas.').
paso(hamburguesa_lentejas, 1, 'Escurre bien las lentejas y machaca. Ralla zanahoria y pica cebolla.').
paso(hamburguesa_lentejas, 2, 'Mezcla lentejas, avena, verduras, comino y sal. Reposa 10 minutos.').
paso(hamburguesa_lentejas, 3, 'Forma dos hamburguesas gruesas o cuatro pequeñas.').
paso(hamburguesa_lentejas, 4, 'Calienta el aceite y cocina a fuego medio de 5 a 6 minutos por lado, hasta que estén firmes.').
paso(hamburguesa_lentejas, 5, 'Tuesta el pan y rellena con las hamburguesas y lechuga lavada y desinfectada.').
paso(garbanzos_espinacas, 1, 'Lava y desinfecta las espinacas. Pica jitomate y ajo.').
paso(garbanzos_espinacas, 2, 'Calienta el aceite y sofríe ajo y paprika unos segundos, sin quemarlos.').
paso(garbanzos_espinacas, 3, 'Agrega jitomate y cocina 8 minutos.').
paso(garbanzos_espinacas, 4, 'Incorpora garbanzos escurridos, espinaca y sal; tapa y cocina 5 minutos.').
paso(garbanzos_espinacas, 5, 'Mezcla hasta que las hojas estén suaves y todo esté caliente. Sirve.').
paso(ensalada_quinoa, 1, 'Enjuaga la quinoa en un colador fino.').
paso(ensalada_quinoa, 2, 'Cuécela con el agua a fuego bajo, tapada, 15 minutos. Reposa 5 minutos y extiende para entibiar.').
paso(ensalada_quinoa, 3, 'Lava el pepino y jitomate; corta en cubos. Lava y pica el perejil.').
paso(ensalada_quinoa, 4, 'Mezcla limón, aceite y sal.').
paso(ensalada_quinoa, 5, 'Junta quinoa y verduras, añade el aderezo y sirve tibia o fría.').
paso(pimientos_quinoa, 1, 'Enjuaga la quinoa y cuécela con el agua 15 minutos. Precalienta el horno a 190 °C.').
paso(pimientos_quinoa, 2, 'Corta los pimientos a lo largo, retira semillas y unta el exterior con aceite.').
paso(pimientos_quinoa, 3, 'Mezcla quinoa, frijoles escurridos, maíz, comino y sal.').
paso(pimientos_quinoa, 4, 'Rellena las mitades y reparte el panela desmoronado encima.').
paso(pimientos_quinoa, 5, 'Hornea de 25 a 30 minutos, hasta que los pimientos estén tiernos.').
paso(arroz_lentejas_cebolla, 1, 'Rebana la cebolla fina. Enjuaga y escurre el arroz.').
paso(arroz_lentejas_cebolla, 2, 'Calienta el aceite y cocina la cebolla a fuego medio-bajo 15 minutos hasta dorarla. Reserva la mitad.').
paso(arroz_lentejas_cebolla, 3, 'Añade arroz, lentejas, comino, agua y sal al sartén con la cebolla restante.').
paso(arroz_lentejas_cebolla, 4, 'Cuando hierva, tapa y cocina a fuego bajo unos 20 minutos. Reposa 5 minutos sin destapar.').
paso(arroz_lentejas_cebolla, 5, 'Mezcla con un tenedor y sirve con la cebolla reservada.').
paso(ensalada_lentejas, 1, 'Escurre las lentejas cocidas y colócalas en un tazón.').
paso(ensalada_lentejas, 2, 'Lava y ralla la zanahoria; pica pepino y cebolla.').
paso(ensalada_lentejas, 3, 'Bate mostaza, limón, aceite y sal hasta integrar.').
paso(ensalada_lentejas, 4, 'Mezcla las lentejas y las verduras con la vinagreta.').
paso(ensalada_lentejas, 5, 'Reparte en dos platos y sirve fría.').
paso(sopa_alubias_tomate, 1, 'Pica jitomate, zanahoria, cebolla y ajo.').
paso(sopa_alubias_tomate, 2, 'Sofríe cebolla y ajo con el aceite 3 minutos.').
paso(sopa_alubias_tomate, 3, 'Añade jitomate y zanahoria y cocina 5 minutos.').
paso(sopa_alubias_tomate, 4, 'Incorpora alubias, agua, orégano y sal. Hierve a fuego bajo 15 minutos.').
paso(sopa_alubias_tomate, 5, 'Machaca algunas alubias para espesar y sirve caliente.').
paso(sopa_champinones, 1, 'Limpia y rebana los champiñones; pica cebolla y ajo.').
paso(sopa_champinones, 2, 'Sofríe cebolla y ajo en el aceite 3 minutos.').
paso(sopa_champinones, 3, 'Añade champiñones y cocina 7 minutos, moviendo.').
paso(sopa_champinones, 4, 'Agrega agua y sal y hierve suavemente 12 minutos.').
paso(sopa_champinones, 5, 'Incorpora el perejil lavado y picado y sirve.').
paso(crema_brocoli, 1, 'Lava el brócoli y córtalo. Pela y corta la papa en cubos pequeños.').
paso(crema_brocoli, 2, 'Sofríe la cebolla picada en el aceite 3 minutos.').
paso(crema_brocoli, 3, 'Agrega papa, brócoli, agua y sal. Tapa y cuece 15 minutos hasta suavizar.').
paso(crema_brocoli, 4, 'Deja entibiar y licúa con la leche.').
paso(crema_brocoli, 5, 'Regresa a la olla y calienta 3 minutos a fuego bajo, moviendo.').
paso(coliflor_especiada, 1, 'Precalienta el horno a 210 °C. Lava la coliflor y divide en ramitos.').
paso(coliflor_especiada, 2, 'Sécala bien para que dore en el horno.').
paso(coliflor_especiada, 3, 'Mezcla con aceite, comino, paprika y sal.').
paso(coliflor_especiada, 4, 'Extiende en una charola sin amontonar y hornea de 25 a 30 minutos; mueve a la mitad.').
paso(coliflor_especiada, 5, 'Cuando esté tierna y dorada, agrega limón y sirve.').
paso(tacos_coliflor, 1, 'Precalienta el horno a 210 °C. Lava y corta la coliflor en ramitos pequeños.').
paso(tacos_coliflor, 2, 'Mezcla con aceite, paprika y sal y extiende en una charola.').
paso(tacos_coliflor, 3, 'Hornea 25 minutos, moviendo a la mitad, hasta dorar y suavizar.').
paso(tacos_coliflor, 4, 'Machaca el aguacate con limón y calienta las tortillas.').
paso(tacos_coliflor, 5, 'Unta aguacate y reparte la coliflor en las tortillas.').
paso(berenjena_horno, 1, 'Precalienta el horno a 200 °C. Lava y corta la berenjena en cubos.').
paso(berenjena_horno, 2, 'Mezcla con la mitad del aceite y extiende en una charola; hornea 20 minutos.').
paso(berenjena_horno, 3, 'Pica jitomate y ajo y mezcla con garbanzos escurridos, comino, sal y aceite restante.').
paso(berenjena_horno, 4, 'Agrega esta mezcla a la charola y remueve con la berenjena.').
paso(berenjena_horno, 5, 'Hornea 15 minutos más, hasta que la berenjena esté muy suave.').
paso(ratatouille, 1, 'Lava las verduras y corta todas en cubos de tamaño parecido.').
paso(ratatouille, 2, 'Sofríe cebolla y ajo en el aceite 4 minutos.').
paso(ratatouille, 3, 'Añade berenjena y pimiento y cocina 8 minutos.').
paso(ratatouille, 4, 'Agrega calabacita, jitomate, orégano y sal. Tapa y cocina a fuego bajo 25 minutos.').
paso(ratatouille, 5, 'Mezcla con cuidado y sirve cuando todas las verduras estén suaves.').
paso(tofu_plancha, 1, 'Escurre el tofu y presiona suavemente con papel; corta en rebanadas.').
paso(tofu_plancha, 2, 'Lava y corta brócoli y zanahoria en piezas pequeñas.').
paso(tofu_plancha, 3, 'Dora el tofu con la mitad del aceite por ambos lados y retira.').
paso(tofu_plancha, 4, 'Saltea las verduras con el aceite restante y jengibre; agrega agua y tapa hasta suavizar.').
paso(tofu_plancha, 5, 'Reincorpora tofu y soya y calienta 2 minutos antes de servir.').
paso(tofu_cacahuate, 1, 'Licúa cacahuate tostado sin cáscara, agua, ajo, limón y soya.').
paso(tofu_cacahuate, 2, 'Escurre, seca y corta el tofu en cubos; rebana el pimiento.').
paso(tofu_cacahuate, 3, 'Dora el tofu con el aceite en un sartén y retira.').
paso(tofu_cacahuate, 4, 'En el mismo sartén cocina el pimiento 5 minutos.').
paso(tofu_cacahuate, 5, 'Regresa el tofu, agrega la salsa y cocina 5 minutos a fuego bajo, moviendo.').
paso(ensalada_col_yogurt, 1, 'Lava y desinfecta la col; corta en tiras muy finas.').
paso(ensalada_col_yogurt, 2, 'Lava, pela y ralla la zanahoria.').
paso(ensalada_col_yogurt, 3, 'Mezcla yogurt, mostaza, limón y sal en un tazón.').
paso(ensalada_col_yogurt, 4, 'Añade col y zanahoria y mezcla hasta cubrir.').
paso(ensalada_col_yogurt, 5, 'Deja reposar 10 minutos en refrigeración antes de repartir.').
paso(ensalada_betabel_nuez, 1, 'Lava los betabeles y cuécelos cubiertos con el agua de 35 a 45 minutos, hasta que se puedan pinchar fácilmente.').
paso(ensalada_betabel_nuez, 2, 'Enfría, pela y corta en cubos.').
paso(ensalada_betabel_nuez, 3, 'Lava y desinfecta la espinaca; pica la nuez y desmorona el queso.').
paso(ensalada_betabel_nuez, 4, 'Mezcla aceite, limón y sal para el aderezo.').
paso(ensalada_betabel_nuez, 5, 'Distribuye espinaca, betabel, queso y nuez en dos platos y agrega el aderezo.').
paso(tostadas_garbanzo_aguacate, 1, 'Escurre los garbanzos y machaca con un tenedor, dejando algunos trozos.').
paso(tostadas_garbanzo_aguacate, 2, 'Abre el aguacate y retira hueso y cáscara.').
paso(tostadas_garbanzo_aguacate, 3, 'Pica la cebolla y mezcla con garbanzo, aguacate, limón y sal.').
paso(tostadas_garbanzo_aguacate, 4, 'Reparte la mezcla sobre las tostadas.').
paso(tostadas_garbanzo_aguacate, 5, 'Sirve inmediatamente para que las tostadas permanezcan crujientes.').
paso(calabacitas_rellenas_arroz, 1, 'Precalienta el horno a 190 °C. Lava las calabacitas y corta a lo largo.').
paso(calabacitas_rellenas_arroz, 2, 'Saca parte de la pulpa con una cuchara sin romper las cáscaras; pícala.').
paso(calabacitas_rellenas_arroz, 3, 'Mezcla pulpa, arroz cocido, maíz, jitomate picado y sal.').
paso(calabacitas_rellenas_arroz, 4, 'Unta las bases con aceite, rellena y cubre con queso.').
paso(calabacitas_rellenas_arroz, 5, 'Hornea de 25 a 30 minutos, hasta que la calabacita esté tierna y el relleno caliente.').
paso(gazpacho_casero, 1, 'Lava las verduras y corta jitomate, pepino y pimiento en trozos.').
paso(gazpacho_casero, 2, 'Retira las semillas del pimiento y pela el ajo.').
paso(gazpacho_casero, 3, 'Licúa las verduras con agua, vinagre y sal hasta obtener una sopa uniforme.').
paso(gazpacho_casero, 4, 'Agrega el aceite y licúa brevemente para integrar.').
paso(gazpacho_casero, 5, 'Sirve frío; si los ingredientes estaban a temperatura ambiente, refrigera antes de servir.').
paso(tabule_bulgur, 1, 'Cuece el bulgur con el agua según su envase; escurre si hace falta y deja entibiar.').
paso(tabule_bulgur, 2, 'Lava y desinfecta el perejil y pícalo muy fino.').
paso(tabule_bulgur, 3, 'Lava y corta jitomate y pepino en cubitos.').
paso(tabule_bulgur, 4, 'Mezcla limón, aceite y sal.').
paso(tabule_bulgur, 5, 'Combina bulgur, verduras y perejil con el aderezo y sirve.').
paso(cuscus_verduras, 1, 'Hierve el agua con la sal, vierte sobre el cuscús y tapa 5 minutos o el tiempo del envase.').
paso(cuscus_verduras, 2, 'Lava y corta las verduras en cubos pequeños.').
paso(cuscus_verduras, 3, 'Saltea las verduras con el aceite y comino hasta que estén tiernas.').
paso(cuscus_verduras, 4, 'Separa los granos del cuscús con un tenedor.').
paso(cuscus_verduras, 5, 'Mezcla con las verduras calientes y reparte en dos platos.').
paso(ensalada_edamame, 1, 'Usa edamame sin vaina y cuécelo en el agua según el envase; escurre y deja entibiar.').
paso(ensalada_edamame, 2, 'Lava el pepino y corta en cubitos.').
paso(ensalada_edamame, 3, 'Tuesta el ajonjolí en un sartén seco unos segundos.').
paso(ensalada_edamame, 4, 'Mezcla soya, vinagre y aceite de sésamo.').
paso(ensalada_edamame, 5, 'Combina edamame y pepino con el aderezo y termina con ajonjolí.').
paso(huevos_champinones, 1, 'Limpia los champiñones y rebánalos; lava y pica el cebollín.').
paso(huevos_champinones, 2, 'Bate los huevos con la sal en un tazón.').
paso(huevos_champinones, 3, 'Calienta el aceite y saltea los hongos 6 minutos, hasta evaporar su líquido.').
paso(huevos_champinones, 4, 'Añade el huevo y remueve a fuego bajo hasta que esté firme, sin partes líquidas.').
paso(huevos_champinones, 5, 'Agrega el cebollín y reparte en dos platos.').
paso(huevos_frijoles, 1, 'Escurre los frijoles y pica la cebolla.').
paso(huevos_frijoles, 2, 'Calienta el aceite y sofríe la cebolla durante 3 minutos.').
paso(huevos_frijoles, 3, 'Agrega los frijoles y machaca ligeramente mientras se calientan.').
paso(huevos_frijoles, 4, 'Bate el huevo con la sal e incorpóralo al sartén.').
paso(huevos_frijoles, 5, 'Remueve a fuego bajo hasta que el huevo esté completamente cocido y sirve.').
paso(huevos_papas, 1, 'Pela las papas y corta en cubos pequeños. Pica la cebolla.').
paso(huevos_papas, 2, 'Calienta el aceite y saltea la papa 5 minutos.').
paso(huevos_papas, 3, 'Añade agua y sal; tapa y cocina 10 minutos, hasta que la papa esté suave.').
paso(huevos_papas, 4, 'Destapa, deja evaporar el agua y agrega la cebolla; cocina 3 minutos.').
paso(huevos_papas, 5, 'Incorpora los huevos batidos y remueve hasta que estén firmes.').
paso(huevos_ahogados, 1, 'Lava y corta los jitomates y el chile.').
paso(huevos_ahogados, 2, 'Licúa con cebolla, ajo, agua y sal.').
paso(huevos_ahogados, 3, 'Calienta el aceite, agrega la salsa y hierve suavemente 12 minutos.').
paso(huevos_ahogados, 4, 'Abre cada huevo en una taza y deslízalo por separado en la salsa.').
paso(huevos_ahogados, 5, 'Tapa y cocina a fuego bajo hasta que clara y yema estén firmes. Sirve con cuidado.').
paso(huevos_motulenos_caseros, 1, 'Licúa jitomate, agua y sal. Cocina la salsa con una cucharada de aceite durante 12 minutos; añade los chícharos y cuece hasta suavizar.').
paso(huevos_motulenos_caseros, 2, 'Machaca y calienta los frijoles. Calienta las tortillas en un comal.').
paso(huevos_motulenos_caseros, 3, 'Pela y rebana el plátano. Dóralo en una cucharada de aceite por ambos lados.').
paso(huevos_motulenos_caseros, 4, 'Cocina los huevos con el aceite restante hasta que estén firmes.').
paso(huevos_motulenos_caseros, 5, 'Unta frijoles sobre las tortillas, coloca los huevos y baña con salsa. Acompaña con plátano.').
paso(migas_huevo, 1, 'Corta las tortillas en cuadritos y pica la cebolla.').
paso(migas_huevo, 2, 'Calienta el aceite y dora la tortilla a fuego medio, moviendo para no quemarla.').
paso(migas_huevo, 3, 'Añade la cebolla y cocina 2 minutos.').
paso(migas_huevo, 4, 'Bate los huevos con sal y viértelos sobre la tortilla.').
paso(migas_huevo, 5, 'Remueve hasta que el huevo esté completamente cocido y sirve caliente.').
paso(tortilla_espanola, 1, 'Pela las papas y rebana muy fino. Rebana la cebolla.').
paso(tortilla_espanola, 2, 'Calienta el aceite en un sartén pequeño; agrega papa, cebolla y sal. Tapa y cocina a fuego bajo 20 minutos, moviendo ocasionalmente.').
paso(tortilla_espanola, 3, 'Bate los huevos y mézclalos con la papa suave en un tazón.').
paso(tortilla_espanola, 4, 'Regresa al sartén y cocina tapado a fuego bajo 7 minutos, hasta que la base esté firme.').
paso(tortilla_espanola, 5, 'Voltea con un plato que cubra el sartén y cocina el otro lado hasta que el centro esté cuajado.').
paso(frittata_brocoli, 1, 'Precalienta el horno a 180 °C y engrasa un refractario pequeño con el aceite.').
paso(frittata_brocoli, 2, 'Corta el brócoli en ramitos; cuécelo en el agua 4 minutos y escurre.').
paso(frittata_brocoli, 3, 'Bate huevos, leche y sal. Desmorona el queso.').
paso(frittata_brocoli, 4, 'Distribuye brócoli y queso en el molde y vierte el huevo.').
paso(frittata_brocoli, 5, 'Hornea de 20 a 25 minutos, hasta que el centro esté firme. Deja reposar 3 minutos antes de cortar.').
paso(shakshuka, 1, 'Pica jitomates, pimiento, cebolla y ajo.').
paso(shakshuka, 2, 'Sofríe cebolla y pimiento en el aceite 7 minutos. Agrega ajo, comino y paprika.').
paso(shakshuka, 3, 'Añade jitomate y sal. Tapa y cocina a fuego bajo 12 minutos.').
paso(shakshuka, 4, 'Haz cuatro huecos en la salsa y coloca un huevo en cada uno.').
paso(shakshuka, 5, 'Tapa y cocina hasta que clara y yema estén firmes. Reparte sin romper los huevos.').
paso(tostada_huevo_aguacate, 1, 'Cubre los huevos con el agua. Cuando hierva, cocina 10 minutos.').
paso(tostada_huevo_aguacate, 2, 'Enfría bajo agua corriente, pela y corta en rebanadas.').
paso(tostada_huevo_aguacate, 3, 'Machaca el aguacate con limón y sal.').
paso(tostada_huevo_aguacate, 4, 'Tuesta el pan en comal o tostador hasta que esté firme.').
paso(tostada_huevo_aguacate, 5, 'Unta aguacate en cada rebanada y distribuye el huevo encima.').
paso(hotcakes_avena_platano, 1, 'Licúa avena, plátano pelado, huevos, leche, polvo de hornear y canela.').
paso(hotcakes_avena_platano, 2, 'Deja reposar la mezcla 5 minutos para que espese.').
paso(hotcakes_avena_platano, 3, 'Calienta un sartén antiadherente a fuego medio-bajo y unta un poco del aceite.').
paso(hotcakes_avena_platano, 4, 'Vierte porciones pequeñas; cocina hasta que aparezcan burbujas y los bordes se vean firmes.').
paso(hotcakes_avena_platano, 5, 'Voltea y cocina el otro lado hasta que el centro no tenga masa cruda. Repite usando el aceite restante.').
paso(hotcakes_clasicos, 1, 'Mezcla harina, polvo de hornear, azúcar y sal.').
paso(hotcakes_clasicos, 2, 'Bate huevo y leche; agrégalos a los secos y mezcla solo hasta integrar.').
paso(hotcakes_clasicos, 3, 'Derrite la mantequilla y reserva la mitad para engrasar el sartén; incorpora la otra mitad a la masa.').
paso(hotcakes_clasicos, 4, 'A fuego medio-bajo vierte porciones pequeñas sobre el sartén engrasado.').
paso(hotcakes_clasicos, 5, 'Cuando aparezcan burbujas, voltea. Cocina hasta que ambos lados estén dorados y el centro cocido.').
paso(pan_frances_canela, 1, 'Bate huevos, leche y canela en un plato hondo.').
paso(pan_frances_canela, 2, 'Sumerge cada rebanada brevemente por ambos lados, sin dejar que se deshaga.').
paso(pan_frances_canela, 3, 'Derrite parte de la mantequilla en un sartén a fuego medio-bajo.').
paso(pan_frances_canela, 4, 'Dora el pan de 2 a 3 minutos por lado, hasta que no queden zonas húmedas de huevo. Repite con la mantequilla restante.').
paso(pan_frances_canela, 5, 'Sirve dos rebanadas por persona y reparte la miel.').
paso(avena_manzana, 1, 'Lava la manzana, retira el corazón y corta en cubitos.').
paso(avena_manzana, 2, 'Calienta la leche con la canela a fuego medio-bajo.').
paso(avena_manzana, 3, 'Agrega avena y manzana cuando la leche esté caliente.').
paso(avena_manzana, 4, 'Cocina de 8 a 10 minutos, moviendo para que no se pegue.').
paso(avena_manzana, 5, 'Apaga cuando espese y la manzana esté suave. Reparte y añade la miel.').
paso(avena_cacao_cacahuate, 1, 'Usa cacahuates tostados sin cáscara y pícalos.').
paso(avena_cacao_cacahuate, 2, 'Disuelve el cacao en un poco de la leche medida.').
paso(avena_cacao_cacahuate, 3, 'Calienta el resto de la leche y agrega avena y cacao disuelto.').
paso(avena_cacao_cacahuate, 4, 'Cocina a fuego bajo de 8 a 10 minutos, moviendo, hasta que la avena esté suave.').
paso(avena_cacao_cacahuate, 5, 'Reparte en dos tazones y termina con miel y cacahuate.').
paso(avena_remojada_almendra, 1, 'Mezcla avena, yogurt, leche y miel en un recipiente limpio con tapa.').
paso(avena_remojada_almendra, 2, 'Tapa y refrigera al menos 8 horas; ese reposo está incluido en el tiempo.').
paso(avena_remojada_almendra, 3, 'Al servir, lava y desinfecta las fresas; córtalas en rebanadas.').
paso(avena_remojada_almendra, 4, 'Pica las almendras y revisa la consistencia de la avena.').
paso(avena_remojada_almendra, 5, 'Divide la avena fría en dos tazones y agrega fresas y almendras.').
paso(yogurt_fruta_nuez, 1, 'Lava y desinfecta las fresas y córtalas.').
paso(yogurt_fruta_nuez, 2, 'Pela el plátano y rebánalo justo antes de servir.').
paso(yogurt_fruta_nuez, 3, 'Pica la nuez y tuesta la avena en un sartén seco 2 minutos; deja enfriar.').
paso(yogurt_fruta_nuez, 4, 'Reparte el yogurt en dos tazones.').
paso(yogurt_fruta_nuez, 5, 'Distribuye fruta, avena y nuez sobre el yogurt y sirve frío.').
paso(chia_coco_mango, 1, 'Mezcla chía, leche de coco y miel en un recipiente limpio.').
paso(chia_coco_mango, 2, 'Espera 10 minutos y vuelve a mezclar para separar grumos.').
paso(chia_coco_mango, 3, 'Tapa y refrigera al menos 4 horas; el reposo está incluido en el tiempo.').
paso(chia_coco_mango, 4, 'Lava y pela el mango y corta la pulpa en cubos.').
paso(chia_coco_mango, 5, 'Divide el pudín frío en dos porciones y añade el mango.').
paso(burrito_huevo_frijol, 1, 'Machaca y calienta los frijoles en una olla pequeña.').
paso(burrito_huevo_frijol, 2, 'Pica la cebolla y sofríe con el aceite 3 minutos.').
paso(burrito_huevo_frijol, 3, 'Bate huevo y sal, agrega al sartén y remueve hasta cocinar completamente.').
paso(burrito_huevo_frijol, 4, 'Calienta las tortillas, reparte frijoles y huevo en el centro.').
paso(burrito_huevo_frijol, 5, 'Dobla los costados y enrolla. Dora cada burrito un minuto por lado en el comal.').
paso(panela_nopales, 1, 'Usa nopales limpios sin espinas. Lava y seca.').
paso(panela_nopales, 2, 'Unta el comal con aceite y asa los nopales por ambos lados hasta suavizarlos.').
paso(panela_nopales, 3, 'Pica jitomate y cebolla y mezcla con la sal.').
paso(panela_nopales, 4, 'Corta el panela en rebanadas gruesas y dora en el comal a fuego medio.').
paso(panela_nopales, 5, 'Sirve el queso sobre los nopales y distribuye el jitomate encima.').
paso(tostada_requeson_miel, 1, 'Tuesta el pan hasta que esté firme y ligeramente dorado.').
paso(tostada_requeson_miel, 2, 'Pica las almendras en trozos pequeños.').
paso(tostada_requeson_miel, 3, 'Mezcla el requesón con la canela.').
paso(tostada_requeson_miel, 4, 'Unta la mezcla sobre las cuatro rebanadas.').
paso(tostada_requeson_miel, 5, 'Reparte miel y almendras encima y sirve de inmediato.').
paso(sandwich_huevo_pepino, 1, 'Hierve los huevos en el agua durante 10 minutos. Enfría, pela y pica.').
paso(sandwich_huevo_pepino, 2, 'Lava el pepino y córtalo en rebanadas delgadas.').
paso(sandwich_huevo_pepino, 3, 'Mezcla huevo, yogurt, mostaza y sal.').
paso(sandwich_huevo_pepino, 4, 'Reparte la mezcla en dos rebanadas y agrega el pepino.').
paso(sandwich_huevo_pepino, 5, 'Cubre con el pan restante, corta por la mitad y sirve.').
paso(crepas_espinaca, 1, 'Bate harina, huevo y leche hasta quitar grumos; deja reposar 10 minutos.').
paso(crepas_espinaca, 2, 'Lava y desinfecta las espinacas. Pica y saltea con una cucharada de aceite; mezcla con requesón y sal.').
paso(crepas_espinaca, 3, 'Unta un sartén con parte del aceite restante y vierte una capa delgada de masa.').
paso(crepas_espinaca, 4, 'Cocina hasta que se despegue, voltea y termina el otro lado. Repite hasta acabar la masa.').
paso(crepas_espinaca, 5, 'Rellena las crepas con espinaca y requesón, dobla y calienta antes de servir.').
paso(muffins_huevo_verdura, 1, 'Precalienta el horno a 180 °C y engrasa seis cavidades de un molde para muffins.').
paso(muffins_huevo_verdura, 2, 'Lava y desinfecta las espinacas; pica junto con el pimiento y el queso.').
paso(muffins_huevo_verdura, 3, 'Bate los huevos con leche y sal, y mezcla con verduras y queso.').
paso(muffins_huevo_verdura, 4, 'Llena las cavidades hasta tres cuartas partes de su capacidad.').
paso(muffins_huevo_verdura, 5, 'Hornea de 20 a 25 minutos, hasta que los centros estén firmes. Reposa 3 minutos antes de desmoldar.').
paso(arroz_leche_canela, 1, 'Enjuaga el arroz y colócalo en una olla con el agua.').
paso(arroz_leche_canela, 2, 'Hierve, baja el fuego y cocina tapado unos 15 minutos, hasta absorber el agua.').
paso(arroz_leche_canela, 3, 'Agrega leche, canela, azúcar y pasas.').
paso(arroz_leche_canela, 4, 'Cocina a fuego bajo de 15 a 20 minutos, moviendo seguido para que no se pegue.').
paso(arroz_leche_canela, 5, 'Cuando el arroz esté muy suave y la mezcla cremosa, apaga y reparte en dos tazones.').
paso(pozole_rojo_pollo, 1, 'Limpia los guajillos, retira semillas y remoja 15 minutos en una taza del agua caliente medida.').
paso(pozole_rojo_pollo, 2, 'Cuece pollo, media cebolla medida y un ajo en el agua restante hasta que el pollo esté bien cocido; deshebra.').
paso(pozole_rojo_pollo, 3, 'Licúa los chiles con su agua y el ajo y cebolla restantes. Cuela la salsa sobre el caldo.').
paso(pozole_rojo_pollo, 4, 'Agrega maíz precocido, pollo, orégano y sal. Hierve suavemente 30 minutos o hasta que el maíz esté suave.').
paso(pozole_rojo_pollo, 5, 'Lava y desinfecta rábanos y lechuga; rebana y sirve sobre el pozole.').
paso(caldo_pollo_verduras, 1, 'Lava las verduras; pela papa y zanahoria y corta en trozos medianos.').
paso(caldo_pollo_verduras, 2, 'Coloca pollo, agua, cebolla y ajo en una olla y lleva a hervor.').
paso(caldo_pollo_verduras, 3, 'Retira la espuma con una cuchara y cocina a fuego medio-bajo 20 minutos.').
paso(caldo_pollo_verduras, 4, 'Agrega papa, zanahoria y sal; cocina 15 minutos. Añade calabacita y cocina 8 minutos más.').
paso(caldo_pollo_verduras, 5, 'Comprueba que el pollo esté totalmente cocido. Agrega cilantro lavado y picado y sirve.').
paso(albondigas_res_arroz, 1, 'Mezcla la carne con arroz cocido, huevo y la mitad de la sal. Forma albóndigas pequeñas.').
paso(albondigas_res_arroz, 2, 'Licúa jitomates, cebolla, ajo y una taza del agua medida.').
paso(albondigas_res_arroz, 3, 'Calienta el aceite en una olla y cocina la salsa 8 minutos.').
paso(albondigas_res_arroz, 4, 'Agrega el agua y sal restantes; cuando hierva suavemente, incorpora las albóndigas.').
paso(albondigas_res_arroz, 5, 'Tapa parcialmente y cocina 25 minutos, hasta que las albóndigas estén completamente cocidas en el centro.').
paso(bistec_mexicana, 1, 'Corta la carne en tiras delgadas y pica las verduras.').
paso(bistec_mexicana, 2, 'Calienta el aceite y cocina la res por tandas hasta que esté bien cocida.').
paso(bistec_mexicana, 3, 'Añade cebolla, ajo y chile; cocina 3 minutos.').
paso(bistec_mexicana, 4, 'Incorpora jitomate y sal, tapa y cocina a fuego bajo de 10 a 12 minutos.').
paso(bistec_mexicana, 5, 'Destapa y deja reducir el líquido si es necesario. Sirve caliente.').
paso(pollo_cremoso_chipotle, 1, 'Corta el pollo en tiras y pica cebolla y ajo.').
paso(pollo_cremoso_chipotle, 2, 'Licúa crema, leche, chipotle y sal.').
paso(pollo_cremoso_chipotle, 3, 'Calienta el aceite y cocina el pollo hasta que esté completamente cocido.').
paso(pollo_cremoso_chipotle, 4, 'Agrega cebolla y ajo y cocina 3 minutos. Vierte la salsa.').
paso(pollo_cremoso_chipotle, 5, 'Cocina a fuego bajo 5 minutos, moviendo y evitando un hervor fuerte. Reparte en dos platos.').
paso(pollo_pipian_verde, 1, 'Cuece el pollo en tres cuartos de litro de agua hasta cocinarlo completamente; reserva el caldo.').
paso(pollo_pipian_verde, 2, 'Cuece tomatillos y chile en el agua restante 10 minutos. Tuesta las semillas en un sartén seco sin quemarlas.').
paso(pollo_pipian_verde, 3, 'Licúa semillas, tomatillos, chile, cebolla, ajo y cilantro lavado con el agua de los tomatillos.').
paso(pollo_pipian_verde, 4, 'Calienta el aceite y cocina la salsa 8 minutos; incorpora poco a poco caldo reservado hasta obtener consistencia de salsa.').
paso(pollo_pipian_verde, 5, 'Agrega pollo y sal; hierve suavemente 10 minutos, moviendo para que no se pegue.').
paso(enchiladas_rojas_pollo, 1, 'Cuece el pollo en tres cuartos de litro de agua hasta que esté bien cocido. Deshebra.').
paso(enchiladas_rojas_pollo, 2, 'Retira tallos y semillas de los chiles. Hiérvelos con jitomates en el agua restante 10 minutos; deja entibiar.').
paso(enchiladas_rojas_pollo, 3, 'Licúa con ajo y sal y cuela. Cocina la salsa con una cucharada de aceite durante 8 minutos.').
paso(enchiladas_rojas_pollo, 4, 'Calienta las tortillas con el aceite restante en un comal; pásalas por la salsa y rellena con pollo.').
paso(enchiladas_rojas_pollo, 5, 'Dobla, reparte en dos platos y termina con la salsa y el queso desmoronado.').
paso(tacos_dorados_papa, 1, 'Pela y corta las papas. Cuécelas en el agua 20 minutos o hasta suavizar.').
paso(tacos_dorados_papa, 2, 'Escurre y machaca con sal. Lava y desinfecta la lechuga y córtala fina.').
paso(tacos_dorados_papa, 3, 'Calienta las tortillas, coloca papa en una orilla y enrolla con firmeza.').
paso(tacos_dorados_papa, 4, 'Calienta el aceite y dora los tacos por tandas, colocando primero la unión hacia abajo.').
paso(tacos_dorados_papa, 5, 'Escurre en papel y sirve con lechuga y queso.').
paso(sopes_frijoles, 1, 'Mezcla la harina de maíz con agua tibia y sal; amasa hasta que no se cuartee.').
paso(sopes_frijoles, 2, 'Forma seis discos gruesos y cuécelos en comal unos 3 minutos por lado.').
paso(sopes_frijoles, 3, 'Cuando puedas tocarlos sin quemarte, pellizca los bordes para formar una orilla.').
paso(sopes_frijoles, 4, 'Dora los sopes con el aceite y calienta los frijoles machacados.').
paso(sopes_frijoles, 5, 'Unta frijoles y reparte queso y lechuga lavada, desinfectada y picada.').
paso(huaraches_nopal, 1, 'Lava y seca los nopales limpios sin espinas.').
paso(huaraches_nopal, 2, 'Asa con la mitad del aceite en un comal hasta que estén suaves por ambos lados.').
paso(huaraches_nopal, 3, 'Calienta el resto del aceite y machaca los frijoles con la sal.').
paso(huaraches_nopal, 4, 'Pica jitomate, cebolla y queso.').
paso(huaraches_nopal, 5, 'Unta los nopales con frijoles y reparte queso, jitomate y cebolla.').
paso(torta_pollo_aguacate, 1, 'Cuece el pollo en el agua con la sal hasta que esté completamente cocido. Deshebra.').
paso(torta_pollo_aguacate, 2, 'Lava y desinfecta la lechuga; rebana jitomate y aguacate.').
paso(torta_pollo_aguacate, 3, 'Abre los bolillos sin separar completamente las mitades.').
paso(torta_pollo_aguacate, 4, 'Calienta el pan en un comal y coloca el pollo caliente dentro.').
paso(torta_pollo_aguacate, 5, 'Reparte aguacate, jitomate y lechuga y cierra las tortas.').
paso(alambre_res, 1, 'Corta carne, pimiento y cebolla en tiras.').
paso(alambre_res, 2, 'Calienta el aceite y cocina la carne hasta que esté bien cocida.').
paso(alambre_res, 3, 'Agrega pimiento, cebolla y sal; saltea 7 minutos hasta suavizar.').
paso(alambre_res, 4, 'Reparte el queso deshebrado sobre el guiso y tapa.').
paso(alambre_res, 5, 'Calienta a fuego bajo hasta derretir el queso y sirve inmediatamente.').
paso(fajitas_pollo_pimientos, 1, 'Corta el pollo en tiras y mezcla con limón, comino y sal.').
paso(fajitas_pollo_pimientos, 2, 'En una tabla limpia, corta pimientos y cebolla en tiras.').
paso(fajitas_pollo_pimientos, 3, 'Calienta el aceite y cocina el pollo hasta que esté completamente cocido.').
paso(fajitas_pollo_pimientos, 4, 'Añade verduras y saltea de 7 a 8 minutos hasta que estén tiernas.').
paso(fajitas_pollo_pimientos, 5, 'Mezcla, apaga el fuego y reparte en dos platos.').
paso(cerdo_salsa_verde, 1, 'Corta el cerdo en cubos pequeños. Lava tomatillos y chile.').
paso(cerdo_salsa_verde, 2, 'Calienta el aceite y dora la carne por todos lados. Agrega medio litro de agua y cocina tapado 30 minutos.').
paso(cerdo_salsa_verde, 3, 'Cuece tomatillos y chile con el agua restante 10 minutos; deja entibiar y licúa con cebolla y ajo.').
paso(cerdo_salsa_verde, 4, 'Vierte la salsa sobre el cerdo, agrega sal y cocina a fuego bajo 20 minutos.').
paso(cerdo_salsa_verde, 5, 'Comprueba que la carne esté suave y completamente cocida antes de servir.').
paso(cochinita_casera, 1, 'Licúa achiote, jugos, ajo, agua y sal.').
paso(cochinita_casera, 2, 'Corta el cerdo en cubos y colócalo con la salsa en una olla de fondo grueso.').
paso(cochinita_casera, 3, 'Tapa y cocina a fuego muy bajo unas 2 horas; revisa que no se seque y mueve ocasionalmente.').
paso(cochinita_casera, 4, 'Cuando esté muy suave y completamente cocido, deshebra con dos tenedores dentro de la salsa.').
paso(cochinita_casera, 5, 'Rebana la cebolla morada y distribúyela sobre la carne al servir.').
paso(crema_poblana, 1, 'Asa los poblanos, tapa en un recipiente 10 minutos y retira piel, tallos y semillas.').
paso(crema_poblana, 2, 'Sofríe la cebolla picada con el aceite 3 minutos.').
paso(crema_poblana, 3, 'Licúa poblanos y cebolla con leche y agua.').
paso(crema_poblana, 4, 'Vierte en una olla, agrega sal y maíz cocido y cocina 8 minutos a fuego bajo.').
paso(crema_poblana, 5, 'Añade la crema y calienta 2 minutos sin hervir fuerte. Sirve caliente.').
paso(crema_elote, 1, 'Pica la cebolla y sofríe en la mantequilla 3 minutos.').
paso(crema_elote, 2, 'Reserva un cuarto de taza del maíz para decorar.').
paso(crema_elote, 3, 'Licúa el resto del maíz con cebolla, leche y agua.').
paso(crema_elote, 4, 'Vierte en una olla y agrega sal. Cocina a fuego bajo 12 minutos, moviendo frecuentemente.').
paso(crema_elote, 5, 'Reparte en dos tazones y agrega los granos reservados.').
paso(sopa_frijol_negro, 1, 'Pica cebolla, ajo y jitomate.').
paso(sopa_frijol_negro, 2, 'Calienta el aceite y sofríe la cebolla y el ajo 3 minutos.').
paso(sopa_frijol_negro, 3, 'Agrega jitomate y comino y cocina 5 minutos.').
paso(sopa_frijol_negro, 4, 'Licúa la mezcla con frijoles y agua; deja entibiar antes de licuar ingredientes calientes.').
paso(sopa_frijol_negro, 5, 'Regresa a la olla, añade sal y hierve suavemente 8 minutos antes de servir.').
paso(arroz_rojo_mexicano, 1, 'Enjuaga y escurre muy bien el arroz. Corta la zanahoria en cubitos.').
paso(arroz_rojo_mexicano, 2, 'Licúa jitomate, cebolla y ajo con el agua.').
paso(arroz_rojo_mexicano, 3, 'Calienta el aceite y dora el arroz 3 minutos, moviendo.').
paso(arroz_rojo_mexicano, 4, 'Agrega la mezcla licuada, zanahoria, chícharos y sal. Al hervir, tapa y baja el fuego.').
paso(arroz_rojo_mexicano, 5, 'Cocina unos 20 minutos sin mover; apaga y deja reposar tapado 5 minutos.').
paso(arroz_verde_poblano, 1, 'Asa, pela y limpia el poblano. Lava y desinfecta espinaca y cilantro.').
paso(arroz_verde_poblano, 2, 'Licúa poblano, hojas, cebolla, ajo y agua.').
paso(arroz_verde_poblano, 3, 'Enjuaga y escurre el arroz; dóralo 3 minutos en el aceite.').
paso(arroz_verde_poblano, 4, 'Añade la mezcla verde y la sal. Cuando hierva, tapa y cocina a fuego bajo 20 minutos.').
paso(arroz_verde_poblano, 5, 'Apaga y reposa 5 minutos sin destapar. Separa los granos con un tenedor.').
paso(frijoles_charros_caseros, 1, 'Pica jitomate, cebolla, chile y cilantro lavado.').
paso(frijoles_charros_caseros, 2, 'Retira la envoltura del chorizo y cocínalo desmenuzado hasta que esté completamente cocido.').
paso(frijoles_charros_caseros, 3, 'Añade cebolla y chile; cocina 3 minutos. Incorpora jitomate y cocina 5 minutos.').
paso(frijoles_charros_caseros, 4, 'Agrega frijoles y agua y hierve a fuego bajo 15 minutos.').
paso(frijoles_charros_caseros, 5, 'Añade el cilantro y sirve caliente; el chorizo ya aporta sal.').
paso(tamales_elote, 1, 'Remoja las hojas limpias en una taza del agua caliente durante 20 minutos; escurre.').
paso(tamales_elote, 2, 'Licúa maíz y leche; mezcla con harina de maíz, mantequilla suave, azúcar y polvo de hornear.').
paso(tamales_elote, 3, 'Reparte en seis hojas, dejando espacio para crecer, y dobla los lados y la punta.').
paso(tamales_elote, 4, 'Coloca el agua restante debajo de la rejilla de una vaporera y acomoda los tamales verticales.').
paso(tamales_elote, 5, 'Tapa y cocina al vapor de 60 a 70 minutos; repón agua caliente si hace falta. Están listos cuando la hoja se desprende y el centro está firme.').
paso(tamales_rajas_queso, 1, 'Remoja las hojas en una taza del agua caliente. Asa y limpia los poblanos y corta en tiras.').
paso(tamales_rajas_queso, 2, 'Mezcla harina, polvo de hornear, sal, aceite y tres cuartos de taza del agua tibia hasta obtener una masa untable.').
paso(tamales_rajas_queso, 3, 'Unta masa en las hojas escurridas; agrega poblano y queso y cierra dejando espacio para crecer.').
paso(tamales_rajas_queso, 4, 'Pon el agua restante bajo la rejilla de una vaporera y acomoda los tamales.').
paso(tamales_rajas_queso, 5, 'Cocina tapados al vapor de 60 a 75 minutos, vigilando el agua. Deja reposar 10 minutos y comprueba que se desprendan de la hoja.').
paso(chiles_rellenos_panela, 1, 'Asa los poblanos, tapa 10 minutos y retira la piel. Haz una abertura lateral y saca las semillas.').
paso(chiles_rellenos_panela, 2, 'Corta el queso en tiras y rellena los chiles sin romperlos.').
paso(chiles_rellenos_panela, 3, 'Licúa jitomate, cebolla, ajo, agua y sal.').
paso(chiles_rellenos_panela, 4, 'Calienta el aceite en una cacerola amplia y cocina la salsa 10 minutos.').
paso(chiles_rellenos_panela, 5, 'Coloca los chiles en la salsa, tapa y cocina a fuego bajo 10 minutos hasta calentar el queso.').
paso(pollo_adobo_guajillo, 1, 'Limpia los chiles, quita semillas y cuece con jitomate en el agua 10 minutos. Deja entibiar.').
paso(pollo_adobo_guajillo, 2, 'Licúa con ajo, comino, orégano y sal; cuela.').
paso(pollo_adobo_guajillo, 3, 'Corta el pollo en trozos y dóralo en el aceite.').
paso(pollo_adobo_guajillo, 4, 'Agrega la salsa, tapa y cocina a fuego bajo de 25 a 30 minutos.').
paso(pollo_adobo_guajillo, 5, 'Comprueba que el pollo esté completamente cocido; mueve la salsa y sirve.').
paso(cerdo_pina_casero, 1, 'Licúa achiote, jugo de naranja, ajo y sal.').
paso(cerdo_pina_casero, 2, 'Corta el cerdo en tiras delgadas y mézclalo con la salsa.').
paso(cerdo_pina_casero, 3, 'Rebana la cebolla y corta la piña en cubos.').
paso(cerdo_pina_casero, 4, 'Calienta el aceite y cocina el cerdo hasta que esté completamente cocido; agrega cebolla y piña.').
paso(cerdo_pina_casero, 5, 'Saltea de 7 a 8 minutos hasta que la cebolla esté suave y la salsa se reduzca.').
paso(tacos_nopal_panela, 1, 'Lava y seca nopales limpios sin espinas; corta en tiras.').
paso(tacos_nopal_panela, 2, 'Rebana la cebolla y saltea con el aceite 3 minutos.').
paso(tacos_nopal_panela, 3, 'Añade nopal y sal y cocina de 10 a 12 minutos, hasta que esté suave y el líquido se reduzca.').
paso(tacos_nopal_panela, 4, 'Dora el panela en cubos en el mismo sartén y mezcla suavemente.').
paso(tacos_nopal_panela, 5, 'Calienta las tortillas, distribuye el relleno y sirve.').
paso(pambazos_papa_chorizo, 1, 'Pela y corta las papas; cuécelas en tres cuartos de litro de agua hasta suavizar. Escurre.').
paso(pambazos_papa_chorizo, 2, 'Limpia los guajillos y cuécelos en el agua restante 10 minutos; licúa con ajo y cuela.').
paso(pambazos_papa_chorizo, 3, 'Cocina el chorizo completamente, agrega las papas y machaca ligeramente.').
paso(pambazos_papa_chorizo, 4, 'Abre el pan, unta su exterior con salsa y dora en un sartén con el aceite.').
paso(pambazos_papa_chorizo, 5, 'Rellena con papa y chorizo y agrega lechuga lavada y desinfectada y crema.').
paso(enchiladas_frijol_poblano, 1, 'Asa los poblanos, tapa 10 minutos, pela y retira semillas; corta en tiras.').
paso(enchiladas_frijol_poblano, 2, 'Calienta los frijoles con la mitad del aceite y machaca.').
paso(enchiladas_frijol_poblano, 3, 'Calienta la salsa verde en una cacerola.').
paso(enchiladas_frijol_poblano, 4, 'Suaviza las tortillas con el aceite restante, rellena con frijol y poblano y dobla.').
paso(enchiladas_frijol_poblano, 5, 'Baña con salsa caliente y reparte el queso encima.').
paso(tostadas_picadillo, 1, 'Pica cebolla y jitomate y ralla la zanahoria. Lava y desinfecta la lechuga y córtala fina.').
paso(tostadas_picadillo, 2, 'Sofríe la cebolla en el aceite 3 minutos y añade la carne.').
paso(tostadas_picadillo, 3, 'Desmenuza mientras se cocina hasta que la carne esté bien cocida.').
paso(tostadas_picadillo, 4, 'Agrega zanahoria, jitomate y sal; tapa y cocina a fuego bajo 12 minutos.').
paso(tostadas_picadillo, 5, 'Distribuye el picadillo sobre tostadas y termina con lechuga.').
